INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2559_Paper_022', 'ซื้อผ้าเช็ดหน้า 3 ผืน กางเกง 4 ตัว ราคา 2,300 บาท ถ้าซื้อผ้า 5 ผืน กางเกง 16 ตัว ราคา 8,500 บาท อยากทราบว่ากางเกง 1 ตัว แพงกว่าผ้าเช็ดหน้า 1 ผืนกี่บาท', '["100 บาท", "200 บาท", "400 บาท", "500 บาท"]', '3', 'ข้อสอบจริง ก.พ. ปี 2559 ชุด Paper

22. ตอบ 3) 400 บาท
กำหนดให้ ผ้าเช็ดหน้าเป็น x และกางเกงเป็น y
3x + 4y = 2,300 - - - - (1)
5x + 16y = 8,500 - - - - (2)
หาค่า x, y จาก (1) x 4 ; 12x + 16y = 9,200 - - - - (3)
(3) – (2) ; (12x + 16y) - (5x + 16y) = 9,200 – 8,500
7x = 700
x = 100
แทน x ในสมการ (1) ; 3(100) + 4y = 2,300
4y = 2,000
y = 500
ผลต่างของ x และ y คือ
y – x = 500 – 100
= 400
ดังนั้น กางเกง 1 ตัว แพงกว่าผ้าเช็ดหน้า 1 ผืน 400 บาท', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2559', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2559_Paper_023', 'นายไก่ผสมสีทาไม้ โดยผสมสีกับทินเนอร์ในอัตราส่วน 1:1.5 ถ้านายไก่ต้องการผสมสีทาไม้ 10 ลิตร อยาก ทราบว่าต้องใช้ทินเนอร์กี่ลิตร', '["4 ลิตร", "5 ลิตร", "6 ลิตร", "7 ลิตร"]', '3', 'ข้อสอบจริง ก.พ. ปี 2559 ชุด Paper

23. ตอบ 3) 6 ลิตร
จากโจทย์สีทาไม้2.5 ลิตร จะใช้อัตราส่วนสีกับทินเนอร์เท่ากับ 1 : 1.5
กำหนดให้ สีทาไม้ 2.5 ลิตร จะใช้ทินเนอร์ 1.5 ลิตร
ต้องการสีทาไม้ 10 ลิตร จะใช้ทินเนอร์ (10 ×1.5)/2.5 = 6 ลิตร
ดังนั้น ต้องใช้ทินเนอร์ 6 ลิตร ในการผสมสีทาไม้10 ลิตร', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2559', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2559_Paper_024', 'ฝันขับรถใช้ความเร็ว 95 ไมล์ต่อชั่วโมง เป็นเวลา 3 ชั่วโมง และเพิ่มความเร็วเป็น 115 ไมล์ต่อชั่วโมง เป็นเวลา 2 ชั่วโมง จงหาว่าฝันขับรถด้วยความเร็วเฉลี่ยเท่าไร', '["100 ไมล์ต่อชั่วโมง", "103 ไมล์ต่อชั่วโมง", "107 ไมล์ต่อชั่วโมง", "109 ไมล์ต่อชั่วโมง"]', '2', 'ข้อสอบจริง ก.พ. ปี 2559 ชุด Paper

24. ตอบ 2) 103 ไมล์ต่อชั่วโมง
หาความเร็วเฉลี่ย = (V₁)(t₁) +(V₂)(t₂)/(t₁+t₂)
= (95(3) +115(2))/(3+2) = 103 ไมล์ต่อชั่วโมง', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2559', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2559_Paper_025', 'นาย ก เงินเดือน 24,000 บาท ถ้า นาย ก ฝากเงิน 10% ของเงินเดือนทุกเดือน และเงินเดือนจะขึ้น 3% ในทุกๆ 6 เดือน อยากทราบว่า เมื่อครบ 2 ปีนาย ก มีเงินฝากเท่าไร', '["112,000 บาท", "66,000 บาท", "60,200 บาท", "57,600 บาท"]', '3', 'ข้อสอบจริง ก.พ. ปี 2559 ชุด Paper

26. ตอบ 3) 60,200 บาท
เดือนที่1 - 6 ; เงินฝาก = 24,000 ×10/100 =2,400 บาท
เดือนที่7 - 12 ; เงินเดือนเพิ่มขึ้น 3% = 24,000 + (24,000 ×(3/100)) =24,720 บาท/เดือน
เงินฝาก = 24,720 ×10/100 =2,472 บาท/เดือน
เดือนที่13 - 18 ; เงินเดือนเพิ่มขึ้น 6% = 24,000 + (24,000 ×(6/100)) =25,440 บาท/เดือน
เงินฝาก = 25,440 ×10/100 =2,544 บาท/เดือน
เดือนที่18 - 24 ; เงินเดือนเพิ่มขึ้น 9% = 24,000 + (24,000 ×9/100) =26,160 บาท/เดือน
