ดังนั้น เมื่อเวลาผ่านไป 2 ปีนาย ก จะมีเงินฝาก เท่ากับ
(2,400 x 6) + (2,472 x 6) + (2,544 x 6) + (2,616 x 6) = 60,192 บาท', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2559', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2559_Paper_026', 'ซื้อของมา 100 ถุง ถุงละ 30 บาท โดยขายราคา 35 บาท จำนวน 20 ถุง และขายในราคา 40 บาท จำนวน 30 ถุง ถ้าต้องการกำไรรวม 35% ถุงที่เหลือต้องขายถุงละกี่บาท', '["33 บาท", "36 บาท", "43 บาท", "45 บาท"]', '3', 'ข้อสอบจริง ก.พ. ปี 2559 ชุด Paper

