INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2559_Paper_027', 'นกขายของให้หวานได้กำไร 10 % ต่อมาหวานขายต่อไปให้คำนึงได้กำไร 5% คำนึงซื้อมาใน ราคา 2,310 บาท อยากทราบว่าต้นทุนที่นกซื้อมาเท่าไร', '["2,000 บาท", "2,050 บาท", "2,100 บาท", "2,310 บาท"]', '1', 'ข้อสอบจริง ก.พ. ปี 2559 ชุด Paper

