INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2559_Paper_029', 'บริจาคเงินมูลนิธิละ 2,500 บาท จะขาดเงินอยู่ 1,000 บาท หากบริจาคมูลนิธิละ 2,000 บาท จะเหลือเงิน 2,500 บาท อยากทราบว่าจำนวนที่จะบริจาคคือเท่าไร', '["16,000 บาท", "16,500 บาท", "17,000 บาท", "17,500 บาท"]', '2', 'ข้อสอบจริง ก.พ. ปี 2559 ชุด Paper

29. ตอบ 2) 16,500 บาท
กรณีเงินขาด ; (X+จำนวนเงินที่ขาด)/จำนวนเงินที่แบ่ง = จำนวนเงินที่แบ่งลงตัว - - - - (1)
กรณีเงินเกิน ; X−จำนวนเงินที่เกิน/จำนวนเงินที่แบ่ง = จำนวนเงินที่แบ่งลงตัว - - - - (2)
(1) = (2) ; (X+จำนวนเงินที่ขาด)/จำนวนเงินที่แบ่ง = (X+จำนวนเงินที่เกิน)/จำนวนเงินที่แบ่ง
(X+1,000)/2,500 = X−2,500/2,000
2,000X + 2,000,000 = 2,500X + 6,250,000
500X = 8,250,000
X = 16,500
