INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2559_Paper_030', 'ปั่นจักรยานสองล้อ ล้อหน้าเส้นผ่าศูนย์กลาง 18 นิ้ว หมุน 30รอบ/นาทีล้อหลังเส้นผ่าศูนย์กลาง 9 นิ้ว จะหมุนกี่รอบต่อนาที', '["15 รอบ/นาที", "45 รอบ/นาที", "60 รอบ/นาที", "90 รอบ/นาที"]', '3', 'ข้อสอบจริง ก.พ. ปี 2559 ชุด Paper

30. ตอบ 3) 60 รอบ/วินาที
