INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2559_Paper_031', 'นาย A เดินทางระยะ 12 กิโลเมตร โดยใช้ความเร็ว 9 กิโลเมตรต่อชั่วโมง หลังจากนั้นเดินทางด้วยความเร็ว 5 กิโลเมตรต่อชั่วโมง เป็นระยะทาง 10 กิโลเมตร และ 16 กิโลเมตรสุดท้าย ใช้ความเร็ว 6 กิโลเมตรต่อชั่วโมง จงหาความเร็วเฉลี่ยในการเดินทาง', '["6 กิโลเมตรต่อชั่วโมง", "6 (1/2) กิโลเมตรต่อชั่วโมง", "6 (1/3) กิโลเมตรต่อชั่วโมง", "7 (1/2) กิโลเมตรต่อชั่วโมง"]', '3', 'ข้อสอบจริง ก.พ. ปี 2559 ชุด Paper

31. ตอบ 3) 6 (1/3) กิโลเมตรต่อชั่วโมง
จากสูตร v = s/t
หา t1 = s/v = 12/9 = 1.33
หา t2 = s/v = 10/5 = 2
หา t3 = s/v = 16/6 = 2.67
จากสูตร v = (s₁+s₂+s₃)/(t₁+t₂+t₃)
= (12+10+16)/(1.33+2+2.67)
= 38/6
= 6 1/3', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2559', 'Paper', 0);
