INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2559_Paper_083', '“ถั่วงอกมีข้อดีต่อเรามากมาย แต่ในขณะเดียวกันถั่วงอกก็มีอันตรายด้วย ซึ่งถั่วงอกจะมีสารที่ชื่อว่า ไตเตด เมื่อสะสมอยู่ในร่างกาย ก็จะส่งผลเสียต่อร่างกาย การกำจัดสารนี้ควรนำไปต้มน้ำเดือดให้สุกก่อน หรือถ้าชอบ รับประทานถั่วงอกดิบๆ ก็ควรระมัดระวังด้วย” ข้อใดคือสาระสำคัญ', '["ข้อดีข้อเสียของถั่วงอก", "อันตรายจากถั่วงอก", "วิธีรับประทานถั่วงอกที่ถูกต้อง", "ประโยชน์ของถั่วงอก"]', '2', 'ข้อสอบจริง ก.พ. ปี 2559 ชุด Paper

