INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2559_Paper_084', '“คุณพ่อ คุณแม่ ควรจะปลูกฝังลูกหลานให้รู้จักใช้รู้จักออม เพราะลูกจะได้เติบโตมาเป็นคนที่มีความสามารถในการจัดการด้านการเงินได้เป็นอย่างดีและรู้จักใช้รู้จักเก็บ ในเวลาที่จะใช้จ่ายในแต่ละครั้งนั้น จะทำให้เด็กรู้จักคุณค่าของเงินมากขึ้น การที่พ่อแม่จะสอนให้ลูกรู้จักการออม พ่อแม่ควรทำตัวให้เป็นแบบอย่างที่ดีก่อน เพราะการเป็นตัวอย่างที่ดีให้ลูกเห็น จะทำให้ลูกปฏิบัติตามง่ายขึ้น” ข้อใดสรุปไม่ถูกต้อง', '["พ่อแม่ควรเป็นแบบอย่างที่ดีให้ลูกปฏิบัติตาม", "พ่อแม่ควรเป็นนักออมที่ดีเพื่อให้ลูกปฏิบัติได้ง่ายขึ้น", "เด็กที่รู้จักใช้รู้จักออม จะเติบโตมาเป็นคนที่ร่ำรวย", "พ่อแม่ควรสอนให้ลูกรู้จักออมตั้งแต่เด็ก"]', '3', 'ข้อสอบจริง ก.พ. ปี 2559 ชุด Paper

