INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2559_Paper_085', '“บรูไนเป็นประเทศที่มีประชากรน้อย ร้อยละ 75 ประกอบอาชีพข้าราชการ และอีกร้อยละ 25 ประกอบ อาชีพเอกชนและพ่อค้า” ข้อใดไม่สอดคล้องกับบทความ', '["ชาวบรูไน “ส่วนใหญ่” เป็นข้าราชการ", "ชาวบรูไน “เกือบทั้งหมด” ไม่เป็นข้าราชการ", "ชาวบรูไน “บางคน” เป็นข้าราชการ", "ชาวบรูไน “ส่วนน้อย” ไม่ใช่ข้าราชการ"]', '2', 'ข้อสอบจริง ก.พ. ปี 2559 ชุด Paper

