INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2559_Paper_086', '“รัฐกัวเป็นสถานที่ท่องเที่ยวและเยี่ยมชมที่มีนักท่องเที่ยวต่างชาติที่เข้ามาในประเทศอินเดียมากที่สุด โดยมีนักท่องเที่ยวต่างชาติคิดเป็น 40% ของนักท่องเที่ยวต่างชาติทั้งหมดที่มาท่องเที่ยวในประเทศอินเดีย” ข้อใดสอดคล้องกับบทความ', '["นักท่องเที่ยวที่มาเที่ยวประเทศอินเดีย ส่วนใหญ่มาเที่ยวรัฐกัว", "นักท่องเที่ยวทุกคนมาเที่ยวรัฐกัว", "นักท่องเที่ยวบางส่วน มาเที่ยวรัฐกัว", "นักท่องเที่ยวเกือบทั้งหมดมาเที่ยวรัฐกัว"]', '3', 'ข้อสอบจริง ก.พ. ปี 2559 ชุด Paper

