INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2559_Paper_087', '“ก๊าซธรรมชาติเป็นเชื้อเพลิงฟอสซิลที่สะอาดที่สุด เพราะทุกหน่วยพลังงานที่ได้จากก๊าซธรรมชาติทำให้เกิดการแพร่กระจายของคาร์บอนไดออกไซด์เพียงครึ่งหนึ่งของถ่านหินและ 1 ใน 4 ของน้ำมันเท่านั้น นอกจากนี้ ก๊าซธรรมชาติยังปลอดสารกำมะถัน ซึ่งเป็นเหตุให้เกิดฝนกรดเช่นเดียวกับถ่านหินและน้ำมัน” ข้อความใดสรุปได้ถูกต้อง', '["ก๊าซธรรมชาติทำให้เกิดการแพร่กระจายของคาร์บอนไดออกไซด์สูง", "ถ่านหินและน้ำมันเป็นสาเหตุให้เกิดฝนกรด", "น้ำมันทำให้เกิดการแพร่กระจายของคาร์บอนไดออกไซด์น้อยกว่าถ่านหิน", "ถ่านหินและน้ำมันไม่มีส่วนผสมของสารกำมะถัน"]', '4', 'ข้อสอบจริง ก.พ. ปี 2559 ชุด Paper

