INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2559_Paper_088', '“ในร่างกายของคนเรามีทั้งเซลล์สร้างเม็ดสีและเซลล์เม็ดเลือดขาว โดยปกติเซลล์เม็ดเลือดขาวมีหน้าที่กำจัดสิ่งแปลกปลอม เช่น เชื้อโรค สารพิษ แต่ด้วยเหตุผลประการที่ยังไม่ทราบแน่ชัด เซลล์เม็ดเลือดขาวมองเห็นเซลล์สร้างเม็ดสีเป็นสิ่งแปลกปลอมจึงกำจัดเซลล์สร้างเม็ดสีซึ่งอยู่ที่ผิวหนัง เกิดเป็นโรคด่างขาว ทำให้ผิวหนังกลายเป็นสีขาวบริเวณกว้างและมีลักษณะเป็นรอยด่างกระจายอยู่ทั่วผิวหนัง” ข้อความข้างต้นกล่าวถึงเรื่องใดเป็นสำคัญ', '["ความผิดปกติของเซลล์สร้างเม็ดสี", "หน้าที่ของเซลล์เม็ดเลือดขาว", "กระบวนการเปลี่ยนสีผิว", "สาเหตุของโรคด่างขาว"]', '4', 'ข้อสอบจริง ก.พ. ปี 2559 ชุด Paper

