INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2559_Paper_089', '“คนไทยรู้จักการนำทรัพยากรธรรมชาติที่ผูกพันกับวิถีท้องถิ่นยาวนานมาทำให้เกิดคุณค่าและงานชิ้นใหม่ เช่น การนำไม้ไผ่มาทำพื้นบ้าน ฝาบ้าน และรั้วบ้านอย่างสวยงาม สะท้อนวิถีชีวิตแบบตะวันออกได้อย่างนุ่มนวล ในขณะที่เหล็ก หิน คอนกรีต ยิ่งใช้ยิ่งหมดไป การใช้ไม้ไผ่ซึ่งเป็นพืชที่ปลูกทดแทนได้เร็วน่าจะเป็นทางเลือกที่ดีกว่า” ข้อความใดไม่สอดคล้องกับข้อความข้างต้น', '["ข้อดีของการใช้ไม้ไผ่คือการประหยัดค่าใช้จ่าย", "ไม้ไผ่เป็นวัสดุที่คนไทยคุ้นเคยมานาน", "เราควรหาวัสดุทดแทนเพื่อใช้ในการก่อสร้าง", "วัสดุที่ใช้ในการก่อสร้างบ่งบอกถึงวัฒนธรรมได้"]', '1', 'ข้อสอบจริง ก.พ. ปี 2559 ชุด Paper

