INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2560_Paper_032', 'เลขเรียงกัน 5 ตัว เลขมากที่สุดบวกกับเลขน้อยที่สุดเท่ากับ 256 จงหาผลรวมของเลขทั้งหมด', '["646", "640", "512", "526"]', '2', 'ข้อสอบจริง ก.พ. ปี 2560 ชุด Paper

