INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2560_Paper_033', 'เครื่องจักร ก. ผลิตสินค้าได้ 500 ชิ้น และสามรถผลิตได้เร็วกว่าเครื่องจักร ข. สองเท่า เครื่องจักร ข. ผลิต สินค้าได้ 500 ชิ้นในเวลา 50 นาทีถ้าให้เครื่องจักร ก. ผลิตสินค้า 7 นาทีจะได้สินค้ากี่ชิ้น', '["120", "130", "140", "150"]', '3', 'ข้อสอบจริง ก.พ. ปี 2560 ชุด Paper

