INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2560_Paper_034', 'ถ้าขาไปรถวิ่งด้วยความเร็ว 60 กิโลเมตรต่อชั่วโมง ได้ระยะทาง 540 กิโลเมตร ขากลับวิ่งด้วยความเร็ว 100 กิโลเมตรต่อชั่วโมง วิ่งได้ เพิ่มอีก 60 กิโลเมตร รวมไปกลับวิ่งด้วยความเร็วเฉลี่ยกี่กิโลเมตรต่อชั่วโมง', '["64", "68", "72", "76"]', '4', 'ข้อสอบจริง ก.พ. ปี 2560 ชุด Paper

34. ตอบ 4) 76
หาเวลาที่ใช้ (t) = ระยะทาง/ความเร็ว
t1= ระยะทาง/ความเร็ว = 540/60 = 9 ชั่วโมง
t2= ระยะทาง/ความเร็ว = (540+60)/100 = 6 ชั่วโมง
หาความเร็วเฉลี่ย = (s₁+s₂)/(t₁+t₂) = (540+(540+60))/(9+6) = 76 กิโลเมตร/ชั่วโมง', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2560', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2560_Paper_035', 'รถ 2 คันขับออกจากโรงงานในเวลาเดียวกัน คัน ก ขับด้วยความเร็ว 80 กิโลเมตรต่อชั่วโมง คัน ข ขับด้วยความเร็ว 120 กิโลเมตรต่อชั่วโมง ถึงจุดหมายก่อนคัน ก 45 นาที อยากทราบว่าระยะทางจากโรงงานมาถึงจุดหมายเท่ากับเท่าใด', '["90 กิโลเมตร", "80 กิโลเมตร", "220 กิโลเมตร", "180 กิโลเมตร"]', '4', 'ข้อสอบจริง ก.พ. ปี 2560 ชุด Paper

35. ตอบ 4) 180 กม.
จากโจทย์คัน ก ขับด้วยความเร็ว 80 กม./ชม ใช้เวลา x+45 นาที
คัน ข ขับด้วยความเร็ว 120กม./ชม. ใช้เวลา 45 นาที
หาเวลาจาก ระยะทาง = (ความเร็ว) x (เวลา)
S1= (80) (X+45) -----------○1
S2= (120) (X) -------------○2
S1= S2; (80) (X+45) = (120) (X)
80X + 3600 = 120X
X = 90 นาทีหรือ 1.5 ชั่วโมง
หาระยะทางจาก ระยะทาง = (ความเร็ว) x (เวลา)
S2= (120) (1.5) = 180 กิโลเมตร', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2560', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2560_Paper_036', 'สนามหญ้าสี่เหลี่ยมมีด้านยาว ยาวกว่า 3 เท่าของด้านกว้างอยู่ 3 เมตร ความยาวรอบสนามหญ้าเท่ากับ 78 เมตร จงหาความยาวของด้านกว้าง', '["18 เมตร", "9 เมตร", "5 เมตร", "3 เมตร"]', '2', 'ข้อสอบจริง ก.พ. ปี 2560 ชุด Paper

36. ตอบ 2) 9 เมตร
จากโจทย์ ด้านยาว ; ยาวกว่า 3 เท่าของด้านกว้างอยู่ 3 เมตร = 3X+3
ด้านกว้าง = X
ความยาวรอบสนาม = 2(ด้านกว้าง) + 2(ด้านยาว)
78 = 2X + 2(3X+3)
78 = 2X + 6X + 6
8X = 72
x = 9 เมตร
ดังนั้น สนามมีด้านกว้าง ยาว 9 เมตร', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2560', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2560_Paper_037', 'สมพรฝากเงินกับธนาคารแห่งหนึ่งเป็นระยะเวลา 10 ปี ปรากฏว่าได้ดอกเบี้ยเท่าเงินต้น อยากทราบว่า ธนาคารคิดดอกเบี้ยในอัตราร้อยละเท่าใด', '["ร้อยละ 10", "ร้อยละ 12", "ร้อยละ 15", "ร้อยละ 18"]', '2', 'ข้อสอบจริง ก.พ. ปี 2560 ชุด Paper

37. ตอบ 2) ร้อยละ 12
จากสูตร ดอกเบี้ยที่ได้ = (เงินฝาก × อัตราดอกเบี้ย× 30)/365
ในกรณีนี้ดอกเบี้ยและเงินต้นเท่ากัน จะได้อัตราดอกเบี้ย = 365/30 ≈ 12
ดังนั้น ธนาคารคิดดอกเบี้ยในอัตราร้อยละ 12', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2560', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2560_Paper_038', 'หมู่บ้านมีหมอต่อประชากร 1:5,000 ถ้ามีประชากร 850,000 คน หมู่บ้านมีหมอ 120 คน ต้องมีหมอเพิ่มอีกกี่คน', '["40 คน", "50 คน", "180 คน", "270 คน"]', '2', 'ข้อสอบจริง ก.พ. ปี 2560 ชุด Paper

