INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2560_Paper_039', 'คะแนนสอบของ ก:ข เท่ากับ 4:5 , ข:ค เท่ากับ 7:6 , ค:ง เท่ากับ 5:3, ง:จ เท่ากับ 2:3 ถ้า ก ได้ 78 คะแนน ใครได้คะแนนเป็นอันดับที่ 4', '["ก", "ข", "ค", "จ"]', '4', 'ข้อสอบจริง ก.พ. ปี 2560 ชุด Paper

39. ตอบ 4) จ
จากโจทย์ก ได้คะแนน 78 คะแนน
ก:ข เท่ากับ 4:5 แสดงว่า ข ได้คะแนน (78×5)/4 = 97.5 คะแนน
ข:ค เท่ากับ 7:6 แสดงว่า ค ได้คะแนน (97.5×6)/7 = 83.57 คะแนน
ค:ง เท่ากับ 5:3 แสดงว่า ง ได้คะแนน (83.57×3)/5 = 50.14 คะแนน
ง:จ เท่ากับ 2:3 แสดงว่า จ ได้คะแนน (50.14×3)/2 = 75.21 คะแนน
ดังนั้น เรียงจากคนได้คะแนนมากไปน้อย ข > ค > ก > จ > ง', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2560', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2560_Paper_040', 'แม่นำเงินมารวมกับพ่อซึ่งมีเงินอยู่ 20 บาท แล้วแบ่งให้ลูก 3 คน คนละ 30 บาท แม่มีเงินกี่บาท', '["60 บาท", "70 บาท", "80 บาท", "90 บาท"]', '2', 'ข้อสอบจริง ก.พ. ปี 2560 ชุด Paper

