INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2560_Paper_041', 'ฟาร์มแห่งหนึ่งเลี้ยงไก่ เป็ด และหมู มีจำนวนไก่ 3/8 ของทั้งหมด มีเป็ดน้อยกว่าไก่ 60 ตัว มีหมู 120 ตัว ฟาร์มแห่งนี้มีสัตว์ทั้งหมดรวมกันกี่ตัว', '["220 ตัว", "240 ตัว", "260 ตัว", "280 ตัว"]', '2', 'ข้อสอบจริง ก.พ. ปี 2560 ชุด Paper

41. ตอบ 2) 240
จากโจทย์จะได้ไก่ 3X ตัว , เป็ด 3X-60 ตัว , หมู120 ตัว และมีสัตว์ทั้งหมด 8X
จะได้สมการ ; (3X) + (3X-60) + 120 = 8X
