INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2560_Paper_042', 'นาย A ขับรถได้ระยะยาง 300 กิโลเมตร/ชั่วโมง โดย 100 กิโลเมตรแรก ขับด้วยความเร็ว 50 กิโลเมตร/ ชั่วโมง 100 กิโลเมตรต่อมา ขับด้วยความเร็ว 100 กิโลเมตร/ชั่วโมง และ 100 กิโลเมตรสุดท้าย ขับด้วยความเร็ว 50 กิโลเมตร/ชั่วโมง จงหาว่านาย A ขับรถด้วยอัตราเร็วเฉลี่ยเท่าไร', '["66 กิโลเมตร/ชั่วโมง", "64 กิโลเมตร/ชั่วโมง", "62 กิโลเมตร/ชั่วโมง", "60 กิโลเมตร/ชั่วโมง"]', '4', 'ข้อสอบจริง ก.พ. ปี 2560 ชุด Paper

42. ตอบ 4) 60 กิโลเมตร/ชั่วโมง
จากสูตร V = s/t
หา t1= s/v = 100/50 = 2 ชั่วโมง
หา t1= s/v = 100/100 = 1 ชั่วโมง
หา t1= s/v = 100/50 = 2 ชั่วโมง
อัตราเร็วเฉลี่ย = s/t
= 300/(2+1+2)
= 60 กิโลเมตร/ชั่วโมง', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2560', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2560_Paper_043', 'รถยนต์คันหนึ่งมีอัตราการใช้น้ำมัน 20 กิโลเมตร/ลิตร ถ้าเติมน้ำมันราคาลิตรละ 40 บาท เป็นเงิน 1,600 บาท รถยนต์คันนี้จะวิ่งได้ระยะทางกี่กิโลเมตร', '["400 กิโลเมตร", "800 กิโลเมตร", "820 กิโลเมตร", "860 กิโลเมตร"]', '2', 'ข้อสอบจริง ก.พ. ปี 2560 ชุด Paper

43. ตอบ 2) 800 กิโลเมตร
