ดังนั้น เงิน 1,600 บาท สามารถซื้อน้ำมันได้ 1,600/40 = 40 ลิตร
น้ำมัน 40 ลิตร สามารถวิ่งได้ 40 x 20 = 800 กิโลเมตร', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2560', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2560_Paper_044', 'ในการพิมพ์จดหมาย 1,000 ฉบับ นาย A ใช้เวลา 4 วัน นาย B ใช้เวลา 5 วัน ถ้าทั้งสองคนช่วยกันพิมพ์จดหมาย 9,000 ฉบับ จะใช้เวลากี่วัน', '["20 วัน", "25 วัน", "30 วัน", "45 วัน"]', '1', 'ข้อสอบจริง ก.พ. ปี 2560 ชุด Paper

44. ตอบ 1) 20 วัน
จากโจทย์1 วัน นาย A จะสามารถพิมพ์จดหมายได้ 1,000/4 = 250 ฉบับ/วัน
