1 วัน ทั้ง 2 คน จะสามารถพิมพ์จดหมายได้ 450 ฉบับ
ดังนั้น การพิมพ์จดหมาย 9,000 ฉบับ ทั้ง 2 คนจะใช้เวลา 9,000/450 = 20 วัน', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2560', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2560_Paper_045', 'สี่เหลี่ยมมุมฉากรูปหนึ่ง กว้าง 2 เมตร ยาว 4 เมตร ตัดมุมออกเป็นรูปสี่เหลี่ยมจัตุรัสยาวด้านละ 30 เซนติเมตร จงหาพื้นที่ที่เหลือ', '["0.764 ตารางเมตร", "7.64 ตารางเมตร", "76.4 ตารางเมตร", "764 ตารางเมตร"]', '2', 'ข้อสอบจริง ก.พ. ปี 2560 ชุด Paper

45. ตอบ 2) 7.64 ตารางเมตร
จากโจทย์สี่เหลี่ยมมุมฉาก กว้าง 2 เมตร ยาว 4 เมตร มีพื้นที่เป็น 8 ตารางเมตร หรือ 80,000 ตารางเซนติเมตร
สี่เหลี่ยมจัตุรัสยาวด้านละ 30 เซนติเมตร มีพื้นที่เป็น 900 ตารางเซนติเมตร
ตัดออก 4 มุม = 900 x 4 = 3600 ตารางเซนติเมตร
ดังนั้น จะเหลือพื้นที่ 80,000 – 3,600 = 76,400 ตารางเซนติเมตร หรือ 7.64 ตารางเมตร', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2560', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2560_Paper_046', 'สินค้าชนิดหนึ่งมีราคาในปีนี้ 250,000 บาท ซึ่งลดลงจากปีที่แล้ว 45% จงหาว่าสินค้าชนิดนี้มีราคาในปีที่แล้วเท่าใด', '["384,615 บาท", "454,545 บาท", "555,555 บาท", "545,545 บาท"]', '2', 'ข้อสอบจริง ก.พ. ปี 2560 ชุด Paper

46. ตอบ 2) 454,545 บาท
กำหนดให้X คือ ราคาสินค้าในปีที่แล้ว
จะได้ X - 45X/100 = 250,000
X – 0.45X = 250,000
0.55 X = 250,000
X = 454,545', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2560', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2560_Paper_047', 'A ขายกระเป๋าให้ B ได้กำไร 25% B ขายให้ C ขาดทุน 40% C ขายให้ D ขาดทุน 30% ถ้า D ซื้อมาในราคา 210 บาท จงหาว่า A ซื้อมาในราคาเท่าใร', '["300 บาท", "400 บาท", "500 บาท", "600 บาท"]', '2', 'ข้อสอบจริง ก.พ. ปี 2560 ชุด Paper

47. ตอบ 2) 400 บาท
จากโจทย์ A ขายให้B = 125% ของราคาต้น
B ขายให้C = 40% ของ 125% = (125×40)/100 = 50%
125% - 50% = 75% ของราคาต้น
C ขายให้D = -30% ของ 75% = (75× (−30))/100 = -22.5%
75% - 22.5% = 52.5% ของราคาที่D ซื้อ
ถ้า 52.5% เท่ากับ 210 บาท
แล้ว 100% เท่ากับ (100×210)/52.5 = 400 บาท', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2560', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2560_Paper_048', 'ได้รับเงินเดือน 25,800 บาท แบ่งเป็นค่าใช้จ่าย 21,000 บาท หากต้องการลดค่าใช้จ่ายเหลือ 1 ใน 3 ของเงินเดือน ต้องลดค่าใช้จ่ายเท่าใด', '["8,600 บาท", "12,000 บาท", "12,400 บาท", "17,200 บาท"]', '3', 'ข้อสอบจริง ก.พ. ปี 2560 ชุด Paper

48. ตอบ 3) 12,400 บาท
จากโจทย์ต้องการลดค่าใช้จ่ายเหลือ 1 ใน 3 ของเงินเดือน = 25,800 x 33.33/100
= 8,599 หรือ ≈ 8,600 บาท
ดังนั้น ต้องลดค่าใช้จ่าย 21,000 – 8,600 = 12,400 บาท', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2560', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2560_Paper_049', 'ถ้า 81ⁿ = 729 แล้ว n มีค่าเท่าใด', '["4/6", "2/3", "6/8", "3/2"]', '4', 'ข้อสอบจริง ก.พ. ปี 2560 ชุด Paper

49. ตอบ 4) 3/2
81ⁿ = 729 → (3⁴)ⁿ = 3⁶ → 3^(4n) = 3⁶
พิจารณาเฉพาะเลขยกกำลัง : 4n = 6 → n = 6/4 หรือ 3/2', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2560', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2560_Paper_050', 'ถ้า x=3, y=2 และ z=-5 แล้ว 3(z + xy) มีค่าเท่าใด', '["3", "6", "9", "12"]', '1', 'ข้อสอบจริง ก.พ. ปี 2560 ชุด Paper

50. ตอบ 1) 3
จากโจทย์นำ x=3, y=2 และ z=-5 ไปแทนค่าใน 3(z + xy)
จะได้3 {-5 + (3x2)} = 3(1) = 3', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2560', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2560_Paper_051', 'ถ้า x=2, y=-3 แล้ว 3(-5 + xy) มีค่าเท่าใด', '["33", "-33", "18", "-18"]', '2', 'ข้อสอบจริง ก.พ. ปี 2560 ชุด Paper

