INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2560_Paper_052', 'จากสมการ 3^(x) = 27⁶ และ 4^(y) = 8⁶ แล้ว 4y² – x² มีค่าเท่าใด', '["32", "16", "5", "0"]', '4', 'ข้อสอบจริง ก.พ. ปี 2560 ชุด Paper

52. ตอบ 4) 0
จากสมการ 3^(x) = 27⁶
3^(x) = (3³)⁶
3^(x) = 3¹⁸
จะได้ X = 18
จากสมการ 4^(y) = 8⁶
(2²)^(y) = (2³)⁶
2^(2y) = 2¹⁸
จะได้ 2y = 18 → y = 9
จากสมการ 4y² – x² = 4(9²) – (18²) = 324 – 324 = 0', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2560', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2560_Paper_053', 'จงหาค่าของ z จากสมการ 3−z/6 = 4z/3', '["1", "1/3", "3", "1/6"]', '2', 'ข้อสอบจริง ก.พ. ปี 2560 ชุด Paper

