INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2560_Paper_054', 'กำหนดให้ 3−2z/6 = z/2 แล้ว z มีค่าเท่าใด', '["2/5", "3/5", "3/7", "4/7"]', '2', 'ข้อสอบจริง ก.พ. ปี 2560 ชุด Paper

