INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2560_Paper_121', '“มะลิ เป็นไม้พุ่มขนาดกลาง ออกดอกเป็นช่อตามปลายกิ่งประมาณ 3 – 5 ดอก แล้วแต่สายพันธุ์ดอกมะลินอกจากจะมีกลิ่นหอมแล้ว ดอกแห้งยังใช้ปรุงเครื่องยาหอมบำรุงหัวใจได้ดี เหตุผลที่ใช้ดอกมะลิเป็นสัญลักษณ์ของวันแม่ เนื่องจากดอกมะลิมีสีขาวบริสุทธิ์ส่งกลิ่นหอมไปไกลและหอมได้นาน ทั้งยังออกดอกตลอดปี เปรียบได้กับความรักอันบริสุทธิ์ของแม่ที่มีต่อลูกไม่มีวันเสื่อมคลาย” บทความข้างต้นไม่ได้กล่าวถึงข้อใด', '["ความหมาย", "ลักษณะทั่วไป", "การขยายพันธุ์", "สรรพคุณทางยา"]', '3', 'ข้อสอบจริง ก.พ. ปี 2560 ชุด Paper

121. ตอบ 3) การขยายพันธุ์', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["ภาษาไทย", "บทความ"]', '2560', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2560_Paper_122', 'ข้อใดไม่สอดคล้องกับคำสัมภาษณ์ต่อไปนี้ “ผมมักจะเขียนย้อนไปเมื่อ 40 – 50 ปีก่อน เพราะความที่เราคุ้นเคยกับสถานที่และผู้คน เวลาเขียนคำพูดหรือเขียนถึงตัวละครมันถนัดกว่า กลมกลืนกว่า ถ้าให้เขียนเรื่องสมัยนี้ รู้ได้เลยว่ามันสะดุด มันไม่งาม ต้องเขียนให้งาม”', '["ขณะนี้ผู้ให้สัมภาษณ์มีอายุ 40 – 50 ปี", "งานของผู้ให้สัมภาษณ์เป็นเรื่องเล่าหรือนวนิยาย", "ผู้ให้สัมภาษณ์คิดว่างานเขียนของตนเองมีคุณภาพ", "ผู้ให้สัมภาษณ์นำสังคมแวดล้อมมาสร้างสรรค์งานเขียน"]', '1', 'ข้อสอบจริง ก.พ. ปี 2560 ชุด Paper

122. ตอบ 1) ขณะนี้ผู้ให้สัมภาษณ์มีอายุ 40 – 50 ปี
สังเกตว่าผู้เขียนมีอายุมากกว่า 50 ปี จากการเขียนย้อนไปเมื่อ 40 – 50 ปีก่อน แสดงว่าเป็นช่วงที่ได้ใช้ชีวิตและ
คุ้นเคยกับช่วงเวลาดังกล่าว', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["ภาษาไทย", "บทความ"]', '2560', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2560_Paper_123', '“เกษตรกร 1.3 ล้านครัวเรือนส่วนมากยากจน มีหนี้สินเฉลี่ย 60,000 บาทต่อครัวเรือน ที่เป็นเช่นนี้เพราะต้นทุนการผลิตสูง เกษตรกรต้องซื้อเมล็ดพันธุ์พืช ปุ๋ย และยาฆ่าแมลงในราคาแพง อีกทั้งบางคนไม่มีที่ดินทำกินเป็นของตนเอง ต้องเช่าที่ดินทำการเกษตร บางปีผลผลิตที่ได้ไม่คุ้มกับเงินที่ลงทุนไป จึงต้องไปกู้เงินจากนายทุนหรือจากธนาคารเพื่อนำมาใช้จ่ายในครอบครัว” ข้อใดเป็นประเด็นสำคัญของข้อความข้างต้น', '["ฐานะ", "แหล่งเงินกู้", "สาเหตุที่ทำให้มีหนี้สิน", "โอกาสในการประกอบอาชีพ"]', '3', 'ข้อสอบจริง ก.พ. ปี 2560 ชุด Paper

123. ตอบ 3) สาเหตุที่ทำให้มีหนี้สิน
ข้อความกล่าวถึงหนี้ของเกษตรกรก่อน จากนั้นบรรยายถึงที่มาของหนี้ว่าเกิดจากสาเหตุใดบ้าง', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["ภาษาไทย", "บทความ"]', '2560', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2560_Paper_124', '“ยาเม็ดหรือแคปซูลควรกลืนทั้งเม็ดพร้อมน้ำ ถ้าระบุว่าเคี้ยวก่อนกลืนต้องเคี้ยงให้ละเอียด หากเป็นยาน้ำควรเขย่าก่อนใช้ทุกครั้งเพื่อให้ตัวยากระจายทั่วขวด ถ้าเป็นยาผงที่ระบุให้ละลายน้ำก่อนรับประทาน ไม่ควรรับประทานทั้งผงแห้ง ๆ แล้วดื่มน้ำตาม เพราะอาจทำให้เกิดการอุดตันของทางเดินอาหารได้” ข้อใดเป็นประเด็นสำคัญของข้อความข้างต้น', '["ข้อแนะนำในการรับประทานยา", "สรรพคุณของยาแต่ละประเภท", "วิธีการเลือกใช้ยาให้ถูกต้องเหมาะสม", "อันตรายจากการใช้ยา"]', '1', 'ข้อสอบจริง ก.พ. ปี 2560 ชุด Paper

124. ตอบ 1) ข้อแนะนำในการรับประทานยา
