INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2560_Paper_125', 'จากข้อความต่อไปนี้ ข้อใดเป็นประโยคลำดับที่ 3', '["“แดจังกึม” เป็นเรื่องที่สะท้อนภาพสังคมราชสำนักเกาหลีในยุคก่อนที่มีการแข่งขันชิงดีชิงเด่นทุกด้าน รวมถึงการทำอาหาร", "ทำให้ผู้ชมจินตนาการตามและเกิดความสงสัยใคร่รู้อยากลองชิมอาหารเกาหลีสักครั้ง", "การพูดถึงรายละเอียดและคุณสมบัติของอาหาร ทั้งในด้านรสชาติและประโยชน์ต่อสุขภาพ รวมถึงภาพของอาหารที่ปรากฏในละคร", "เดินเรื่องได้รวดเร็ว ชวนติดตาม ให้คนดูได้ลุ้นว่านางเอกจะทำอาหารได้ชนะใจราชสำนักหรือไม่"]', '3', 'ข้อสอบจริง ก.พ. ปี 2560 ชุด Paper

125. ตอบ 3) การพูดถึงรายละเอียดและคุณสมบัติของอาหาร ทั้งในด้านรสชาติและประโยชน์ต่อสุขภาพ รวมถึง
ภาพของอาหารที่ปรากฏในละคร
เรียบเรียงเป็นบทความได้ตามลำดับเป็น 1 – 4 – 3 - 2 ดังนี้
“แดจังกึม” เป็นเรื่องที่สะท้อนภาพสังคมราชสำนักเกาหลีในยุคก่อนที่มีการแข่งขันชิงดีชิงเด่นทุกด้าน
รวมถึงการทำอาหาร เดินเรื่องได้รวดเร็ว ชวนติดตาม ให้คนดูได้ลุ้นว่านางเอกจะทำอาหารได้ชนะใจราชสำนัก
หรือไม่ การพูดถึงรายละเอียดและคุณสมบัติของอาหาร ทั้งในด้านรสชาติและประโยชน์ต่อสุขภาพ รวมถึงภาพ
ของอาหารที่ปรากฏในละคร ทำให้ผู้ชมจินตนาการตามและเกิดความสงสัยใคร่รู้อยากลองชิมอาหารเกาหลีสักครั้ง', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["ภาษาไทย", "เรียงประโยค"]', '2560', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2560_Paper_126', 'จากข้อความต่อไปนี้ ข้อใดเป็นประโยคลำดับที่ 4', '["แพทย์แนะนำว่า ผู้ป่วยโรคไตต้องเลือกรับประทานอาหารเพื่อให้ได้ประโยชน์ต่อร่างกายสูงสุด", "ผู้ป่วยโรคไตมักมีความกังวลเรื่องอาหารว่าหากรับประทานมากเกินไปจะทำให้เสี่ยงต่อการเกิดภาวะไตวาย หรือหากรับประทานน้อยเกินไปก็อาจทำให้เกิดการขาดสารอาหาร", "ควรหลีกเลี่ยงอาหาร ผักและผลไม้ที่มีสีเข้ม เพราะอาจจะมีโพแทสเซียมและฟอสฟอรัสสูง พร้อมเปลี่ยนมารับประทานอาหารที่มีรสจืด สีสันอ่อน", "โดยเฉพาะอย่างยิ่งผู้ป่วยที่ต้องฟอกไตหรือล้างไตทางหน้าท้อง ซึ่งต้องระวังเรื่องอาหารมากเป็นพิเศษ"]', '3', 'ข้อสอบจริง ก.พ. ปี 2560 ชุด Paper

126. ตอบ 3) ควรหลีกเลี่ยงอาหาร ผักและผลไม้ที่มีสีเข้ม เพราะอาจจะมีโพแทสเซียมและฟอสฟอรัสสูง พร้อม
เปลี่ยนมารับประทานอาหารที่มีรสจืด สีสันอ่อน
เรียบเรียงเป็นบทความได้ตามลำดับเป็น 2 – 1 – 4 - 3 ดังนี้
ผู้ป่วยโรคไตมักมีความกังวลเรื่องอาหารว่าหากรับประทานมากเกินไปจะทำให้เสี่ยงต่อการเกิดภาวะไต
วาย หรือหากรับประทานน้อยเกินไปก็อาจทำให้เกิดการขาดสารอาหาร แพทย์แนะนำว่า ผู้ป่วยโรคไตต้องเลือก
รับประทานอาหารเพื่อให้ได้ประโยชน์ต่อร่างกายสูงสุด โดยเฉพาะอย่างยิ่งผู้ป่วยที่ต้องฟอกไตหรือล้างไตทางหน้า
ท้อง ซึ่งต้องระวังเรื่องอาหารมากเป็นพิเศษ ควรหลีกเลี่ยงอาหาร ผักและผลไม้ที่มีสีเข้ม เพราะอาจจะมี
โพแทสเซียมและฟอสฟอรัสสูง พร้อมเปลี่ยนมารับประทานอาหารที่มีรสจืด สีสันอ่อน', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["ภาษาไทย", "เรียงประโยค"]', '2560', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2560_Paper_127', 'จากข้อความต่อไปนี้ข้อใดเป็นประโยคลำดับที่ 1', '["จากการสำรวจในประเทศไทย พบว่ากว่า 60% ของขยะมาจากขยะอาหาร", "สร้างก๊าซเรือนกระจกถึง 8% ในขณะที่คนกว่า 830 ล้านคนทั่วโลกกลับประสบภาวะอดอยาก", "คนไทย 1 คน สร้างขยะอาหารสูงถึง 254 กิโลกรัมต่อปีเลยทีเดียว", "ในแต่ละปี อาหารกว่า 1,300 ล้านตัน หรือ 1 ใน 3 ของอาหารที่ผลิตได้ทั่วโลก ต้องกลายเป็นขยะอาหารที่ถูกทิ้งไปอย่างสูญเปล่า"]', '4', 'ข้อสอบจริง ก.พ. ปี 2560 ชุด Paper

127. ตอบ 4) ในแต่ละปี อาหารกว่า 1,300 ล้านตัน หรือ 1 ใน 3 ของอาหารที่ผลิตได้ทั่วโลก ต้องกลายเป็นขยะ
อาหารที่ถูกทิ้งไปอย่างสูญเปล่า
เรียบเรียงเป็นบทความได้ตามลำดับเป็น 4 – 2 – 1 – 3 ดังนี้
ในแต่ละปี อาหารกว่า 1,300 ล้านตัน หรือ 1 ใน 3 ของอาหารที่ผลิตได้ทั่วโลก ต้องกลายเป็นขยะอาหาร
ที่ถูกทิ้งไปอย่างสูญเปล่า สร้างก๊าซเรือนกระจกถึง 8% ในขณะที่คนกว่า 830 ล้านคนทั่วโลกกลับประสบภาวะอด
