INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2560_Paper_149', 'Surasit give me a book _______ birthday.', '["at", "in", "on", "to"]', '3', 'ข้อสอบจริง ก.พ. ปี 2560 ชุด Paper

