INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2561_Paper_001', '7 * 12 = 361
13 * 14 = 729
19 * 22 = ?', '["1,225", "1,369", "1,521", "1,681"]', '4', 'ข้อสอบจริง ก.พ. ปี 2561 ชุด Paper

1. ตอบ 4) 1,681
จากโจทย์ 7 * 12 = 361 → (7+12)² = 361
13 * 14 = 729 → (13+14)² = 729
ดังนั้น 19 * 22 = ? → (19+22)² = 1,681', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป", "โอเปอเรชัน"]', '2561', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2561_Paper_002', '7 * 5 = 37
6 * 2 = 16
8 * 3 = ?', '["27", "28", "29", "30"]', '3', 'ข้อสอบจริง ก.พ. ปี 2561 ชุด Paper

2. ตอบ 3) 29
จากโจทย์ 7 * 5 = 37 → (7x5) + (7-5) = 37
6 * 2 = 16 → (6x2)+ (6-2) = 16
ดังนั้น 8 * 3 = ? → (8x3)+ (8-3) = 29', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป", "โอเปอเรชัน"]', '2561', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2561_Paper_003', 'ถ้าแจกหนังสือให้โรงเรียน โรงเรียนละ 1 เล่ม จะเหลือหนังสืออยู่ 6 เล่ม ถ้าแจกหนังสือให้โรงเรียนละ 2 เล่ม จะมีโรงเรียนที่ไม่ได้หนังสืออยู่ 5 โรงเรียน จงหาว่ามีหนังสือทั้งหมดกี่เล่ม', '["20", "21", "22", "24"]', '3', 'ข้อสอบจริง ก.พ. ปี 2561 ชุด Paper

3. ตอบ 3) 22 เล่ม
กำหนดให้X = จำนวนโรงเรียน , กรณีหนังสือขาด ; N-5 , กรณีหนังสือเกิน ; N+6
แจกหนังสือ 1 เล่ม ; 1(N+6) = N+6
แจกหนังสือ 2 เล่ม ; 2(N-5) = 2N-10
จะได้ N+6 = 2N-10
N = 16
ดังนั้น แทน N ใน สมการ N+6 = 16+2 = 22 เล่ม', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2561', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2561_Paper_004', 'รถยนต์สองคันอยู่ห่างกัน 40 กิโลเมตร วิ่งเข้าหากัน รถคันแรกวิ่งด้วยความเร็ว 40 กิโลเมตรต่อชั่วโมง คันที่สองวิ่งด้วยความเร็ว 60 กิโลเมตรต่อชั่วโมง มีแมลงวันอยู่หน้ารถคันหนึ่งบินด้วยความเร็ว 80 กิโลเมตรต่อ ชั่วโมง ไปยังรถอีกคันหนึ่ง พอไปถึงแล้วบินกลับมาที่รถอีกคัน บินสลับอย่างนี้เรื่อยไปจนรถทั้งสองคันวิ่งมาชน กัน ถามว่าแมลงวันตัวนี้บินได้ระยะทางกี่กิโลเมตร', '["30 กิโลเมตร", "32 กิโลเมตร", "34 กิโลเมตร", "36 กิโลเมตร"]', '2', 'ข้อสอบจริง ก.พ. ปี 2561 ชุด Paper

4. ตอบ 2) 32 กิโลเมตร
จากโจทย์แมลงวันบินความเร็ว 80 กิโลเมตรต่อ ต้องการหาระยะทางที่แมลงวันบิน
หาเวลาที่รถทั้ง 2 คัน จะชนกัน จะได้ v₁ + v₂ = s/t
40 + 60 = 40/t
t = (4/10) ชั่วโมง
หาระยะทางที่แมลงวันบิน = 80 × 4/10 = 32 กิโลเมตร', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2561', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2561_Paper_005', 'ถ้า A, B, C มีเงินรวมกัน 1,760 บาท เงินของแต่ละคน คิดเป็นอัตราส่วน 4 : 5 : 2 ตามลำดับ คนที่มีเงินมากที่สุด มีเงินมากกว่าคนที่มีเงินน้อยที่สุดกี่บาท', '["320 บาท", "450 บาท", "480 บาท", "520 บาท"]', '3', 'ข้อสอบจริง ก.พ. ปี 2561 ชุด Paper

5. ตอบ 3) 480 บาท
A มีเงินอยู่= 1,760 x 4/11 = 640 บาท
B มีเงินอยู่= 1,760 x 5/11 = 800 บาท
C มีเงินอยู่= 1,760 x 2/11 = 320 บาท
ดังนั้น คนที่มีเงินมากที่สุด มีเงินมากกว่าคนที่มีเงินน้อยที่สุดอยู่800 – 320 = 480 บาท', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2561', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2561_Paper_006', 'กำหนดให้4x - 3y = 8 แล้ว 6y - 8x มีค่าเท่ากับเท่าไหร่', '["-8", "8", "16", "-16"]', '4', 'ข้อสอบจริง ก.พ. ปี 2561 ชุด Paper

6. ตอบ 4) -16
จากสมการ 4x - 3y = 8 จะได้ y = 4x−8/3
แทน y = 4x−8/3 ใน 6y - 8x ; จะได้ ^(6(4x−8)/3)−8x
= ^(6(4x−8)/3)−8x
= (8x - 16) – 8x = -16', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2561', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2561_Paper_007', 'โรงงานมีพนักงานรวมทั้งหมด 300 คน เป็นพนักงานธุรการ 1 ใน 3 ของจำนวนพนักงานทั้งหมด ในปีต่อมา ลดจำนวนพนักงานธุรการลงครึ่งหนึ่ง อยากทราบว่าจำนวนพนักงานธุรการในปัจจุบันคิดเป็นกี่เปอร์เซ็นของ จำนวนพนักงานทั้งหมดในปัจจุบัน', '["20%", "25%", "16%", "10 %"]', '1', 'ข้อสอบจริง ก.พ. ปี 2561 ชุด Paper

7. ตอบ 1) 20%
จากโจทย์ พนักงานรวมทั้งหมด 300 คน เป็นพนักงานธุรการ 1 ใน 3
มีพนักงานธุรการอยู่ 300/3 = 100 คน
จำนวนพนักงานธุรการลงครึ่งหนึ่ง เหลือพนักงานธุรการอยู่ 50 คน
ดังนั้น จะเหลือพนักงานธุรการในปัจจุบันคิดเป็น (50×100)/250 = 20 %', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2561', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2561_Paper_008', 'ในสนามแข่งรถแทนอยู่ห่างจากธรรม 60 เมตร ธรรมอยู่ด้านหลังแทน ถ้าแทนขับต่อด้วยความเร็ว 4 เมตรต่อวินาทีธรรมขับด้วยความเร็ว 5 เมตรต่อวินาที อยากทราบว่าแทนจะขับไปได้ระยะทางกี่เมตร ธรรมจึงจะแซง', '["120 เมตร", "240 เมตร", "300 เมตร", "360 เมตร"]', '2', 'ข้อสอบจริง ก.พ. ปี 2561 ชุด Paper

8. ตอบ 2) 240 เมตร
จากสูตร S₁/V₁ = S₂/V₂
จะได้ X−60/4 = X/5
5(X-60) = 4X
5X - 300 = 4X
X = 300
ดังนั้น ขับไปได้ระยะทาง 300 – 60 = 240 เมตร ธรรมจึงจะแซง', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2561', 'Paper', 0);
