INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2561_Paper_012', 'พ่อมีเงิน 3,000,000 บาท ให้ภรรยา 10% ให้ลูกคนกลางมากกว่าลูกคนโต 100% ให้ลูกคนเล็กมากกว่า คนกลาง 50 % ลูกคนเล็กได้เงินเท่าไหร่', '["450,000", "500,000", "490,000", "1,350,000"]', '4', 'ข้อสอบจริง ก.พ. ปี 2561 ชุด Paper

12. ตอบ 4) 1,350,000 บาท
จากโจทย์ให้ภรรยา 10% จะได้เท่ากับ (3,000,000 ×10)/100 = 300,000 บาท
กำหนดให้ให้เงินลูกคนโต เป็น X บาท
ให้เงินลูกคนกลางมากกว่าลูกคนโต 100% เป็น 2X บาท
ให้เงินลูกคนเล็กมากกว่า คนกลาง 150 % เป็น 3X บาท
จะได้ X + 2X + 3X = 2,700,000
X = 450,00’
ดังนั้น ลูกคนเล็กได้เงิน 3X = 3(450,000) = 1,350,000 บาท', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2561', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2561_Paper_013', 'A ลงทุนเปิดร้าน 90,000 บาท 6 เดือนต่อมา B ร่วมลงทุนอีก 100,000 บาท โดยทั้งสองคนลงทุนด้วยเงินจำนวนเท่าเดิมทุกๆ 6 เดือน เมื่อครบ 2ปี ได้กำไร 66,000 บาท ถ้าแบ่งกำไรตามสัดส่วนการลงทุน อยากทราบว่า A ได้กำไรกี่บาท', '["30,000 บาท", "32,000 บาท", "34,000 บาท", "36,000 บาท"]', '4', 'ข้อสอบจริง ก.พ. ปี 2561 ชุด Paper

13. ตอบ 4) 36,000 บาท
B = 100,000 B = 100,000 B = 100,000
A = 90,000 A = 90,000 A = 90,000 A = 90,000 กำไร 66,000
○1 ---------------------------○2 ---------------------------○3 ---------------------------○4 --------------------------○5
6เดือน 6เดือน 6เดือน 6เดือน
จากโจทย์ A ลงทุนไปทั้งหมด 360,000 บาท
B ลงทุนไปทั้งหมด 300,000 บาท
คิดเป็นสัดส่วน A:B = 360,000:300,000 หรือ 6:5
เมื่อแบ่งกำไรตามสัดส่วนการลงทุน A จะได้กำไร = (66,000 ×6)/(6+5) = 36,000 บาท', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2561', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2561_Paper_014', 'กำหนดให้(2x - 5) (4x² + 10x + 25) = 387 แล้ว (x³ + 8) มีค่าเท่าไร', '["54", "64", "72", "82"]', '3', 'ข้อสอบจริง ก.พ. ปี 2561 ชุด Paper

