INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2561_Paper_053', '“หลักสำคัญของแผนน้ำประปาปลอดภัย เริ่มตั้งแต่การดูแลรักษาแหล่งน้ำดิบตั้งแต่ต้นทาง เมื่อน้ำดิบเข้าสู่โรงงานผลิตน้ำประปาจะต้องคุมจุดเสี่ยงทั้งระบบผลิต ระบบสูบส่งและสูบจ่ายทางท่อ เพื่อดูแลรักษาคุณภาพน้ำอย่างต่อเนื่อง รวมไปถึงการควบคุมการวางท่อ การซ่อมท่อ การเปลี่ยนท่อเก่าที่หมดอายุ เพื่อความสะอาดของน้ำจนไปถึงบ้านเรือนประชาชน” ข้อใดเป็นประเด็นสำคัญของบทความข้างต้น', '["การควบคุมคุณภาพน้ำประปา", "กระบวนการผลิตน้ำประปา", "การจ่ายน้ำประปาสู่ชุมชน", "การตรวจสอบแหล่งน้ำดิบ"]', '1', 'ข้อสอบจริง ก.พ. ปี 2561 ชุด Paper

