INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2561_Paper_054', '“คำพูดของพ่อแม่อาจทำให้ลูกเกิดความเข้าใจไม่ตรงกันและทำให้เกิดปัญหาตามมาได้ เช่น พ่อแม่รักและเป็นห่วงลูกเรื่องการทำการบ้านหรือการอ่านหนังสือเพื่อเตรียมตัวสอบ แต่ถ้าคำพูดของพ่อแม่เป็นไปในลักษณะพร่ำบ่น ลูกอาจเข้าใจผิดคิดว่าพ่อแม่เคี่ยวเข็ญและก้าวก่ายชีวิตส่วนตัวมากเกินไป จึงต้องมีการอธิบายเพื่อให้เกิดความเข้าใจซึ่งกันและกัน ลูกจะได้เข้าใจว่าพ่อแม่หวังดีต่อตน” ข้อใดเป็นประเด็นสำคัญของบทความข้างต้น', '["การอบรมสั่งสอนลูก", "ความหวังดีของพ่อแม่", "การสื่อสารในครอบครัว", "โลกส่วนตัวของเด็ก"]', '3', 'ข้อสอบจริง ก.พ. ปี 2561 ชุด Paper

