INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2561_Paper_055', '“เมื่อไฟเริ่มไหม้บ้านเรือน คนแรก ๆ ที่เห็นรีบกดสัญญาณแจ้งเตือน เมื่อได้ยินสัญญาณ พนักงานดับเพลิงรีบรุดไปยังที่เกิดเหตุพร้อมรถน้ำ อุปกรณ์ และน้ำยาเคมี แล้วเริ่มปฏิบัติการดับไฟอย่างรวดเร็ว แต่โทสะไม่สามารถใช้สิ่งใดดับได้เหมือนไฟ นอกจากเจ้าของโทสะนั้นจะมีขันติ ความอดทน อดกลั้น และการรู้อภัยต่อผู้อื่น” จากบทความข้างต้น ผู้เขียนต้องการเน้นสาระเรื่องใดเป็นสำคัญ', '["เหตุการณ์ขณะเกิดไฟไหม้", "คุณธรรมที่ทุกคนควรมี", "ขั้นตอนการดับเพลิง", "วิธีระงับความโกรธ"]', '4', 'ข้อสอบจริง ก.พ. ปี 2561 ชุด Paper

