INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2561_Paper_059', 'จากข้อความต่อไปนี้ ข้อใดเป็นประโยคลำดับที่ 4', '["นำไปสู่ข้อสรุปที่ว่า ความเครียดเป็นอันตรายกับเราเมื่อเราคิดว่ามันอันตราย คนที่มองความเครียดในแง่ร้ายมักจะพยายามหลีกเลี่ยงมันให้ถึงที่สุด", "สำหรับกลุ่มคนที่มีระดับความเครียดสูงแต่ไม่เชื่อว่ามันจะเป็นอันตรายกลับมีโอกาสเสี่ยงต่อการเสียชีวิตน้อยที่สุดในกลุ่มอาสาสมัครในการทดลอง", "ตรงกันข้ามกับคนที่มองความเครียดเป็นเรื่องดี มักจะหาทางออก หาตัวช่วย และมีวิธีการจัดการกับความเครียดและสถานการณ์ต่าง ๆ ได้ดี คนกลุ่มนี้มองปัญหาเป็นเรื่องท้าทาย", "มีการค้นพบว่าความเครียดมีผลทำให้เกิดความเสี่ยงต่อการเสียชีวิตมากถึง 43% แต่จะเกิดขึ้นเฉพาะกลุ่มคนที่เชื่อว่าความเครียดเป็นเรื่องอันตรายเท่านั้น"]', '2', 'ข้อสอบจริง ก.พ. ปี 2561 ชุด Paper

59. ตอบ 2) สำหรับกลุ่มคนที่มีระดับความเครียดสูงแต่ไม่เชื่อว่ามันจะเป็นอันตรายกลับมีโอกาสเสี่ยงต่อการ
เสียชีวิตน้อยที่สุดในกลุ่มอาสาสมัครในการทดลอง
เรียบเรียงเป็นบทความได้เป็น 4 – 1 – 3 - 2 ดังนี้
มีการค้นพบว่าความเครียดมีผลทำให้เกิดความเสี่ยงต่อการเสียชีวิตมากถึง 43% แต่จะเกิดขึ้นเฉพาะกลุ่ม
คนที่เชื่อว่าความเครียดเป็นเรื่องอันตรายเท่านั้น นำไปสู่ข้อสรุปที่ว่า ความเครียดเป็นอันตรายกับเราเมื่อเราคิดว่า
มันอันตราย คนที่มองความเครียดในแง่ร้ายมักจะพยายามหลีกเลี่ยงมันให้ถึงที่สุด ตรงกันข้ามกับคนที่มอง
