INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2561_Paper_062', 'จากข้อความต่อไปนี้ ข้อใดเป็นประโยคลำดับที่ 4', '["การทดลองในหนูที่กินอาหารประเภทเนื้อสัตว์มากกว่า 20% จะทำให้เพิ่มอัตราการเติบโตของเนื้องอกถึง 3 เท่าของหนูที่ถูกจำกัดให้กินอาหารประเภทเนื้อสัตว์ 5%", "จำนวนและขนาดของเซลล์เนื้องอกจะถูกกำหนดโดยปริมาณโปรตีนที่ร่างกายรับเข้าไป", "อาหารประเภทผักและผลไม้ยังมี Antioxidant ช่วยให้ร่างกายต่อสู้กับอนุมูลอิสระ โดยปรับสภาพของอนุมูลอิสระก่อนที่มันจะไปทำร้ายเซลล์", "การกินโปรตีนจากพืชไม่ได้เป็นตัวเร่งทำให้เกิดโรคมะเร็ง ดังนั้นการเปลี่ยนมากินโปรตีนพืชน่าจะเป็นทางเลือกที่ดีกว่า"]', '3', 'ข้อสอบจริง ก.พ. ปี 2561 ชุด Paper

62. ตอบ 3) อาหารประเภทผักและผลไม้ยังมี Antioxidant ช่วยให้ร่างกายต่อสู้กับอนุมูลอิสระ โดยปรับสภาพ
ของอนุมูลอิสระก่อนที่มันจะไปทำร้ายเซลล์
เรียบเรียงเป็นบทความได้เป็น 1 – 2 – 4 – 3 ดังนี้
การทดลองในหนูที่กินอาหารประเภทเนื้อสัตว์มากกว่า 20% จะทำให้เพิ่มอัตราการเติบโตของเนื้องอกถึง
3 เท่าของหนูที่ถูกจำกัดให้กินอาหารประเภทเนื้อสัตว์ 5% จำนวนและขนาดของเซลล์เนื้องอกจะถูกกำหนดโดย
ปริมาณโปรตีนที่ร่างกายรับเข้าไป การกินโปรตีนจากพืชไม่ได้เป็นตัวเร่งทำให้เกิดโรคมะเร็ง ดังนั้นการเปลี่ยนมา
กินโปรตีนพืชน่าจะเป็นทางเลือกที่ดีกว่า อาหารประเภทผักและผลไม้ยังมี Antioxidant ช่วยให้ร่างกายต่อสู้กับ
อนุมูลอิสระ โดยปรับสภาพของอนุมูลอิสระก่อนที่มันจะไปทำร้ายเซลล์', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["ภาษาไทย", "เรียงประโยค"]', '2561', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2561_Paper_063', 'In the hotel
Mr. Sandals : Hi, I have a reservation under the name of Sandals.
Receptionist : .... (1) ....
Mr. Sandals : Of course! Let me take it out of my wallet.
Receptionist : Thank you, sir. Now, .... (2) ....
Mr. Sandals : Yes, of course. Is American Express okay ?
Receptionist : .... (3) .... Only VISA or MasterCard.
Mr. Sandals : In that case, here''s my VISA.
Receptionist : Thank you. Your room number is 507, queen bed, nonsmoking. Is that agreeable to you, sir?
Mr. Sandals : Yes, .... (4) ....
Receptionist : Very good .... (5) .... If you need anything at all, please dial 0.

Select the best word/phrase to fill in blank (1).', '["May I help you ?", "Yes, come in please.", "Could I see your ID, lease ?", "Here''s your room key."]', '3', 'ข้อสอบจริง ก.พ. ปี 2561 ชุด Paper

1. ตอบ 3) Could I see your ID, lease ?
1. May I help you ? ให้ฉันช่วยคุณไหม
2. Yes, come in please. ได้เชิญเข้ามาข้างในได้เลย
3. Could I see your ID, lease ? ฉันขอดูบัตรประจำตัวของคุณได้ไหม
4. Here''s your room key. นี่คือกุญแจห้องของคุณ', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["บทสนทนา"]', '2561', 'Paper', 0);
