INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2561_Paper_067', 'In the hotel
Mr. Sandals : Hi, I have a reservation under the name of Sandals.
Receptionist : .... (1) ....
Mr. Sandals : Of course! Let me take it out of my wallet.
