INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2561_Paper_068', 'Make certain that you return a damage product before the warranty ....', '["respires", "inspires", "expires", "perspires"]', '3', 'ข้อสอบจริง ก.พ. ปี 2561 ชุด Paper

6. ตอบ 3) expires
Make certain that you return a damage product before the warranty . . . ..
คำแปล : ตรวจสอบให้แน่ใจว่าคุณคืนสินค้าที่เสียหายก่อนการรับประกัน . . . .
1. respires สูดหายใจ
2. inspires แรงบันดาลใจ
3. expires หมดอายุ
4. perspires เหงื่อซึม', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2561', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2561_Paper_069', 'I have selected the most .... ones, as I know we have a limited amount of money to spend.', '["costly", "physical", "attractive", "affordable"]', '4', 'ข้อสอบจริง ก.พ. ปี 2561 ชุด Paper

7. ตอบ 4) affordable
I have selected the most . . . . ones, as I know we have a limited amount of money to spend.
ฉันเลือกอันที่. . . . ที่สุด เพราะฉันรู้ว่าพวกเรามีเงินสำหรับใช้จ่ายอย่างจำกัด
1. costly ราคาแพง
2. physical กายภาพ
3. attractive ดึงดูดใจ
4. affordable สามารถจ่ายได้', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2561', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2561_Paper_070', 'It was difficult to .... because of the noise from the building construction outside the school.', '["accurate", "depreciate", "concentrate", "obligate"]', '3', 'ข้อสอบจริง ก.พ. ปี 2561 ชุด Paper

8. ตอบ 3) concentrate
It was difficult to . . . . because of the noise from the building construction outside the school.
คำแปล : มันเป็นเรื่องยากสำหรับ . . . . เพราะเสียงจากการก่อสร้างตึกด้านนอกโรงเรียน
1. accurate ถูกต้อง, แม่นยำ
2. depreciate ลดค่า
3. concentrate การจดจ่อ, มีสมาธิ
4. obligate ภาระหน้าที่', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2561', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2561_Paper_071', 'His secretary was .... to cancel all his engagements.', '["instructed", "requested", "declared", "informed"]', '1', 'ข้อสอบจริง ก.พ. ปี 2561 ชุด Paper

9. ตอบ 1) instructed
His secretary was . . . . to cancel all his engagements.
คำแปล : เลขาของเขาถูก . . . . ให้ยกเลิกการนัดหมายของเขาทั้งหมด
1. instructed สั่ง
2. requested ร้องขอ
3. declared แจ้ง, ประกาศ
4. informed แจ้ง, รายงาน', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2561', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2561_Paper_072', 'This is the employee''s .... not to disclose confidential company information to individuals.', '["specification", "revision", "reputation", "obligation"]', '4', 'ข้อสอบจริง ก.พ. ปี 2561 ชุด Paper

10. ตอบ 4) obligation
This is the employee''s . . . . not to disclose confidential company information to individuals.
คำแปล : นี่เป็น . . . . ของพนักงาน ที่จะไม่เปิดเผยข้อมูลลับของบริษัทให้กับบุคคลอื่น
1. specification เฉพาะเจาะจง
2. revision ปรับปรุงแก้ไข
3. reputation ความโด่งดัง
4. obligation ภาระหน้าที่', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2561', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2561_Paper_073', 'Doesn''t the girl look .... when a dark shadow appears ?', '["fright", "frighten", "frighteningly", "frightening"]', '4', 'ข้อสอบจริง ก.พ. ปี 2561 ชุด Paper

11. ตอบ 4) frightening
Doesn''t the girl look . . . . when a dark shadow appears ?
คำแปล : เด็กผู้หญิงดูเหมือน . . (หวาดกลัว/ตกใจ) . . เมื่อมีเงาดำปรากฏขึ้น
ใช้ adj. เพื่อขยายคำนาม ‘the girl’
1. fright (n.)
2. frighten (v.)
3. frighteningly (adv.)
4. frightening (adj.)', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2561', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2561_Paper_074', 'We expect that fewer guests will .... the evening gala.', '["attend", "attending", "attention", "attendance"]', '1', 'ข้อสอบจริง ก.พ. ปี 2561 ชุด Paper

12. ตอบ 1) attend
We expect that fewer guests will . . . . the evening gala.
คำแปล : พวกเราคาดว่าจะมีแขก . . (เข้าร่วม) . . ลดลงในงานเลี้ยงช่วงเย็น
ใช้ will + v.1 ซึ่งกริยาช่องที่ 1 ในตัวเลือก คือ attend', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2561', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2561_Paper_075', '.... the storm, the airline suspends flight to various destinations.', '["due to", "any", "rather", "just"]', '1', 'ข้อสอบจริง ก.พ. ปี 2561 ชุด Paper

13. ตอบ 1) due to
. . . . the storm, the airline suspends flight to various destinations.
คำแปล : . . (เนื่องจาก) . . มีพายุสายการบินจึงระงับเที่ยวบินที่ไปยังจุดหมายปลายทางต่าง ๆ
คำเชื่อมสำหรับบอกเหตุผล due to + n.
ใช้ any กรณีเป็นประโยคคำถามหรือประโยคปฏิเสธ', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2561', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2561_Paper_076', 'I knew no human saw me that night .... the police received information on me.', '["to", "for", "yet", "so"]', '3', 'ข้อสอบจริง ก.พ. ปี 2561 ชุด Paper

14. ตอบ 3) yet
I knew no human saw me that night . . . . the police received information on me.
คำแปล : ฉันรู้ว่าไม่มีใครเห็นฉันในคืนนั้น . . . . ตำรวจได้รับข้อมูลของฉัน
1. to ถึง
2. for เพื่อ
3. yet อย่างไรก็ดี(กรณีใช้เป็นคำเชื่อม)
4. so ดังนั้น', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2561', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2561_Paper_077', '.... of the competitors was badly affected by the extreme heat and passed out.', '["Some", "One", "A few", "No"]', '2', 'ข้อสอบจริง ก.พ. ปี 2561 ชุด Paper

15. ตอบ 2) One
. . . . of the competitors was badly affected by the extreme heat and passed out.
คำแปล : . . . . ผู้เข้าแข่งขันได้รับผลกระทบอย่างรุนแรงจากความร้อนจัดจนเป็นลมหมดสติ
สังเกตคำว่า was ต้องใช้กับประธานที่เป็นเอกพจน์ซึ่งมีอยู่ 2 ตัวเลือก คือ one และ no
แต่no ไม่สามารถใช้กับ . . . . + of N. ได้จึงตอบ one', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2561', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2561_Paper_078', 'The film Great Expectations is based on the novel by Charles Dickens, with .... work I am quite familiar.', '["whom", "who", "what", "whose"]', '4', 'ข้อสอบจริง ก.พ. ปี 2561 ชุด Paper

16. ตอบ 4) whose
The film Great Expectations is based on the novel by Charles Dickens, with . . . . work I am quite
familiar.
คำแปล : ภาพยนตร์เรื่อง Great Expectations สร้างจากนวนิยายของ Charles Dickens ซึ่งฉันคุ้นเคยกับผลงาน
ของเขาเป็นอย่างดี
ใช้ whose + n. เพื่อแสดงความเป็นเจ้าของ', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2561', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2561_Paper_079', 'I wish you .... to repair the car yourself. You have made the problem worse actually.', '["hadn''t attempted", "haven''t attempted", "didn''t attempt", "won''t attempt"]', '1', 'ข้อสอบจริง ก.พ. ปี 2561 ชุด Paper

17. ตอบ 1) hadn''t attempted
I wish you . . . . to repair the car yourself. You have made the problem worse actually.
คำแปล : ฉันหวังว่าคุณจะ . . (ไม่พยายาม) . . ซ่อมรถด้วยตัวเอง คุณยิ่งทำให้ปัญหาแย่ลงไปอีก
สังเกตรูปของประโยคบ่งบอกว่า เขาได้พยายามซ่อมไปแล้ว (ซึ่งมันแย่กว่าเดิม)
แสดงว่าประโยคหน้า I wish + . . . เป็นรูปอดีต (past perfect)
จะได้โครงสร้างเป็น I wish + subject + had/hadn’t + v.3 ตรงกับตัวเลือกที่1', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2561', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2561_Paper_080', 'Animals .... to survive in the wild, rather than kept in captivity.', '["have been helping", "are helping", "should be helped", "ought to have helped"]', '3', 'ข้อสอบจริง ก.พ. ปี 2561 ชุด Paper

18. ตอบ 3) should be helped
Animals . . . . to survive in the wild, rather than kept in captivity.
คำแปล : สัตว์. . (ควรถูกช่วย) . . ให้มีชีวิตรอดในป่ามากกว่าการถูกเลี้ยงไว้ในกรง
สังเกตว่าสัตว์ถูกกระทำ ดังนั้น จึงต้องเป็น passive voice : should + v.to be + v.3 ตรงกับตัวเลือกที่3', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2561', 'Paper', 0);
