INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2562_Paper_001', 'ฝากเงิน 1,500,000 บาท ได้ดอกเบี้ยร้อยละ 4.5 ต่อปี ถ้าฝากครบ 5 ปีจะได้ดอกเบี้ยกี่บาท', '["337,500 บาท", "375,000 บาท", "437,500 บาท", "475,000 บาท"]', '1', 'ข้อสอบจริง ก.พ. ปี 2562 ชุด Paper

1. ตอบ 1) 337,500 บาท
