INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2562_Paper_002', 'ปัจจุบันอายุของ A B C รวมกันได้ 40 ปี อีก 3 ปีข้างหน้า A จะมีอายุ 23 ปี และอายุของ B จะเพิ่มขึ้นจากนี้ 20% ถามว่าปีนี้ C อายุเท่าใด', '["3 ปี", "7 ปี", "5 ปี", "8 ปี"]', '3', 'ข้อสอบจริง ก.พ. ปี 2562 ชุด Paper

