INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2562_Paper_003', 'พนักงานทั้งหมด 3,138 คน ทำแบบทดสอบประเมิน 3,009 คน คิดเป็นกี่เปอร์เซ็นต์', '["88%", "102%", "96%", "108%"]', '3', 'ข้อสอบจริง ก.พ. ปี 2562 ชุด Paper

