INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2562_Paper_004', 'เลขจำนวนคู่3 จำนวนเรียงลำดับกัน รวมกันได้ 36 ผลคูณของเลข 2 จำนวนหลัง จะมีค่าเท่าใด', '["160", "174", "168", "180"]', '3', 'ข้อสอบจริง ก.พ. ปี 2562 ชุด Paper

4. ตอบ 168
กำหนดให้เลขจำนวนคู่ 3 เป็น X, X+2, X+4
จะได้ X + (X+2) + (X+4) = 36
3X + 6 = 36
X = 10
เลขคู่3 จำนวนเรียงลำดับกัน คือ X=10, X+2=12 และ X+4=14
ดังนั้น ผลคูณของเลข 2 จำนวนหลัง จะมีค่าเท่ากับ 12x14 = 168', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2562', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2562_Paper_005', 'ถ้า a = 2b และ c = 2a ดังนั้น a + b + c มีค่าเท่าใด', '["5b", "7b", "6b", "8b"]', '2', 'ข้อสอบจริง ก.พ. ปี 2562 ชุด Paper

