c = 4b
ดังนั้น a + b + c มีค่าเท่ากับ 2b + b + 4b = 7b', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2562', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2562_Paper_006', 'โรงเรียนแห่งหนึ่งมีนักเรียนหญิง 3/8 ของนักเรียนทั้งหมด วันหนึ่งมีนักเรียนไม่มาโรงเรียนคิดเป็นนักเรียนหญิงเท่ากับ 1/9 ของนักเรียนหญิงทั้งหมด และนักเรียนชาย 1/10 ของนักเรียนชายทั้งหมด ถ้าในวันนั้นมีนักเรียนมาโรงเรียน 645 คน โรงเรียนแห่งนี้นักเรียนหญิงน้อยกว่านักเรียนชายกี่คน', '["180 คน", "250 คน", "270 คน", "450 คน"]', '1', 'ข้อสอบจริง ก.พ. ปี 2562 ชุด Paper

6. ตอบ 1) 180 คน
กำหนดให้ นักเรียนหญิง 3/8 ของนักเรียนทั้งหมดเป็น (3/8)x
จะได้นักเรียนชาย 5/8 ของนักเรียนทั้งหมดเป็น (5/8)x
จากโจทย์นักเรียนหญิงที่ไม่มาเท่ากับ 1/9 ของนักเรียนหญิงทั้งหมดเป็น (1/9)((3/8)x)
นักเรียนชายที่ไม่มา 1/10 ของนักเรียนชายทั้งหมดเป็น (1/10)((5/8)x)
จะได้สมการ [(3/8)x+(5/8)x]−[(1/9)((3/8)x)+(1/10)((5/8)x)] =645
[(8/8)x]−[((3/72)x)+((5/80)x)] =645
[(8/8)x]−[((10/96)x)] =645
X=720
หาจำนวนนักเรียน ; จำนวนนักเรียนหญิง 3/8 (720)=270
จำนวนนักเรียนหญิง (5/8) (720)=450
ดังนั้น โรงเรียนแห่งนี้นักเรียนหญิงน้อยกว่านักเรียนชาย 450 – 270 = 180 คน', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2562', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2562_Paper_007', 'A มีเงิน 120% ของ B ส่วน B มีเงิน 80% ของ C ถ้า B มีเงิน 1,400 บาท ทั้งสามคนมีเงินรวมกันกี่บาท', '["4,730 บาท", "4,930 บาท", "5,030 บาท", "4,830 บาท"]', '4', 'ข้อสอบจริง ก.พ. ปี 2562 ชุด Paper

7. ตอบ 4,830 บาท
กำหนดให้ A มีเงิน 120% ของ B เป็น 120%B - - - - (1)
B มีเงิน 80% ของ C เป็น 80%C = 1,400 - - - - (2)
C มีเงินเป็น C = X
จะได้ เงินของ A = (120/100) (1,400) = 1,680 บาท
