INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2562_Paper_008', '3 * 2 = 9
2 * 4 = 22
5 * 3 = ?', '["17", "24", "28", "31"]', '1', 'ข้อสอบจริง ก.พ. ปี 2562 ชุด Paper

8. ตอบ 1) 17
จากความสัมพันธ์ (หน้า+หลัง) + หลัง² = ผลลัพธ์
จะได้ (3 + 2) + 2² = 5 + 4 = 9
(2 + 4) + 4² = 6 + 16 = 22
ดังนั้น (5 + 3) + 3² = 8 + 9 = 17', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป", "โอเปอเรชัน"]', '2562', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2562_Paper_009', '8 * 5 = 9
9 * 3 = 36
15 * 7 = ?', '["49", "64", "91", "128"]', '2', 'ข้อสอบจริง ก.พ. ปี 2562 ชุด Paper

9. ตอบ 2) 64
จากความสัมพันธ์ (หน้า – หลัง)² = ผลลัพธ์
จะได้ (8 - 5)² = 3² = 9
(9 - 3)² = 6² = 36
ดังนั้น (15 – 7)² = 8² = 64', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป", "โอเปอเรชัน"]', '2562', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2562_Paper_010', 'ลูกบากศ์มีพื้นที่ผิวรวม 150 ตารางนิ้ว ต้องการทราบว่าลูกบาศก์นี้มีปริมาตรกี่ลูกบากศ์นิ้ว', '["75 ลูกบากศ์นิ้ว", "100 ลูกบากศ์นิ้ว", "125 ลูกบากศ์นิ้ว", "150 ลูกบากศ์นิ้ว"]', '3', 'ข้อสอบจริง ก.พ. ปี 2562 ชุด Paper

10. ตอบ 3) 125 ลูกบากศ์นิ้ว
พื้นที่ผิวของลูกบาศก์ = 6(ด้าน x ด้าน)
กำหนดให้แต่ละด้านของลูกบาศก์ เป็น X
จะได้ว่า 150 = 6(X²)
X² = 25
X = 5
ปริมาตรของลูกบาศก์= ด้าน x ด้าน x ด้าน
ดังนั้น ลูกบาศก์มีปริมาตร 5 x 5 x 5 = 125 ลูกบากศ์นิ้ว', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2562', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2562_Paper_011', 'สินค้าราคา 960 บาท ขายลดราคา 20% ราคาสินค้าที่ขายกับราคาที่ติดป้าย คิดเป็นอัตราส่วนเท่าใด', '["4 : 3", "3 : 4", "4 : 5", "5 : 4"]', '1', 'ข้อสอบจริง ก.พ. ปี 2562 ชุด Paper

11. ตอบ 1) 4 : 3
จากโจทย์สินค้าราคาป้าย X บาท ลด 20% จะขายในราคา 960 บาท
ถ้าสินค้า ราคาป้าย 100 บาท ลด 20% จะขายในราคา 80 บาท
จะได้ สินค้าขายในราคา 960 บาท ราคาป้าย = (960×100)/80 = 1,200 บาท
ดังนั้น ราคาสินค้าที่ขายกับราคาที่ติดป้าย คิดเป็นอัตราส่วน 1200:960 หรือ 3.75:3', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2562', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2562_Paper_012', 'อัตราส่วนเหรียญทองต่อเหรียญเงินต่อเหรียญทองแดงเป็น 3:5:7 ถ้ามีเหรียญทองอยู่ 15 เหรียญ จะมีเหรียญทองแดงกี่เหรียญ', '["15 เหรียญ", "25 เหรียญ", "35 เหรียญ", "75 เหรียญ"]', '3', 'ข้อสอบจริง ก.พ. ปี 2562 ชุด Paper

12. ตอบ 3) 35 เหรียญ
จากโจทย์ ทอง:เงิน:ทองแดง = 3:5:7 และมีเหรียญทองอยู่ 15 เหรียญ
หาจำนวนทั้งหมด ; 15 = (3/15)x → X = 75 เหรียญ
จะมีเหรียญทองแดง = (7/15) (75) = 35 เหรียญ
ดังนั้น จะมีเหรียญทองแดง 35 เหรียญ', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2562', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2562_Paper_013', 'ถ้า 2x+3y = 6x-y ≠ 0 แล้ว 7x−y/(x+y) เท่ากับเท่าใด', '["3", "4", "5", "6"]', '1', 'ข้อสอบจริง ก.พ. ปี 2562 ชุด Paper

13. ตอบ 1) 3
จากสมการ 2x+3y = 6x-y
3y+y = 6x-2x
y = x
แทนค่า y = x ในสมการ 7x−x/(x+x) = 6x/(2x) = 3', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2562', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2562_Paper_014', 'จำนวนสามจำนวนเรียงกัน โดยสามจำนวนนี้หารด้วย 3 ลงตัว และมีผลรวมเท่ากับ 45 จงหาผลคูณของเลขทั้งสามจำนวนนี้', '["3,240", "3,750", "4,280", "4,560"]', '1', 'ข้อสอบจริง ก.พ. ปี 2562 ชุด Paper

