ดังนั้น ผลคูณของเลขทั้งสามจำนวนเท่ากับ 12x15x18 = 3,240', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2562', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2562_Paper_015', 'สี่เหลี่ยมจัตุรัสความยาวแต่ละด้านเพิ่มขึ้น 12 ซม. ทำให้พื้นที่สี่เหลี่ยมเพิ่มขึ้น 200 ตารางซม. จงหาว่าเดิมสี่เหลี่ยมรูปนี้มีเส้นรอบรูปเท่าไร', '["9", "9 1/3", "10", "10 1/3"]', '2', 'ข้อสอบจริง ก.พ. ปี 2562 ชุด Paper

15. ตอบ 2) 9 1/3
กำหนดให้ ความยาวแต่ละด้านเพิ่มขึ้น 12 ซม คือ X+12 และ Y คือ พื้นที่สี่เหลี่ยม
จะได้ (X)(X) = Y - - - - (1)
(X+12)(X+12) = Y+200 - - - - (2)
จาก (2) ; (X+12)(X+12) = Y+200
X²+ 24X + 144 = Y+200
Y = X²+ 24X -56
จาก (1) ; X² = Y แทนใน Y = X²+ 24X -56
X² = X²+ 24X -56
24X = 56
X = (56/24)
ดังนั้น สี่เหลี่ยมรูปนี้มีเส้นรอบรูป = 4X = 4 (56/24) = 224/24 หรือ 9 8/24 หรือ 9(1/3)', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2562', 'Paper', 0);
