INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2562_Paper_067', 'จากเงื่อนไขต่อไปนี้จงตอบคำถามข้อ 62 - 66
- การเดินทางไปเที่ยวต่างจังหวัด มีผู้ร่วมเดินทาง คือ สุริยา จันทร์ดวงดาว เมฆา ไปเที่ยวจังหวัด 4 จังหวัด ได้แก่เชียงใหม่ขอนแก่น กาญจนบุรีภูเก็ต และเดินทางโดยรถยนต์ส่วนตัว เครื่องบิน รถไฟ
- แต่ละคนไปได้ไม่เกิน 2 จังหวัด และการเดินทางไปแต่ละจังหวัดจะใช้พาหนะแตกต่างกัน
- สุริยาเดินทางไปเชียงใหม่โดยเครื่องบินและไม่ไปภูเก็ต
- เมฆาเดินทางไปกาญจนบุรีโดยรถยนต์ส่วนตัวและไปขอนแก่นโดยเครื่องบิน
- จันทร์กับดวงดาว เดินทางไปภูเก็ตด้วยกันทางรถยนต์
- จันทร์ไม่เดินทางไปเที่ยวกับสุริยา
- มี2 คน ไปเชียงใหม่
- มีคนไปกาญจนบุรีแค่คนเดียวและมีคนเดินทางด้วยรถไฟแค่คนเดียว
- มีคนที่เดินทางไปเชียงใหม่ 1คน เดินทางด้วยรถไป

ข้อสรุปที่ 1: ถ้าสุริยาเดินทางไปขอนแก่น จันทร์จะเดินทางไปภูเก็ตจังหวัดเดียว
ข้อสรุปที่ 2: ถ้าจันทร์เดินทางด้วยเครื่องบินสุริยาจะเดินทางด้วยรถยนต์', '["ข้อสรุปทั้งสองเป็นจริงตามเงื่อนไข", "ข้อสรุปทั้งสองไม่เป็นจริงตามเงื่อนไข", "ข้อสรุปทั้งสองไม่แน่ชัด (ไม่สามารถสรุปได้ว่าจริงหรือไม่จริง)", "ข้อสรุปทั้งสองมีข้อสรุปใดข้อสรุปหนึ่งที่เป็นจริง หรือไม่จริง หรือไม่แน่ชัด ซึ่งไม่ซ้ำกัน"]', '4', 'ข้อสอบจริง ก.พ. ปี 2562 ชุด Paper

66. ข้อสรุปที่1 ถ้าสุริยาเดินทางไปขอนแก่น จันทร์จะเดินทางไปภูเก็ตจังหวัดเดียว จริง
ข้อสรุปที่2 ถ้าจันทร์เดินทางด้วยเครื่องบินสุริยาจะเดินทางด้วยรถยนต์ ไม่แน่ชัด', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["เงื่อนไขภาษา"]', '2562', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2562_Paper_068', '“ผู้ที่ออกกำลังกายหรือเล่นกีฬาเป็นประจำ เมื่อหยุดออกกำลังกายจะอ้วนเร็วกว่าคนที่ไม่เคยออกกำลังกายเลย ทั้งนี้อาจเกิดจากขณะที่เขาออกกำลังกายนั้นมีการใช้พลังงานสมดุลกับการรับประทานอาหาร แต่เมื่อหยุดออกกำลังกายแล้วยังรับประทานอาหารในปริมาณเท่าเดิม จึงส่งผลให้เกิดความไม่สมดุลกัน” ข้อใดเป็นจุดประสงค์ของผู้เขียนบทความข้างต้น', '["ให้ความรู้เรื่องการออกกำลังกายอย่างถูกต้อง", "อธิบายสาเหตุที่ผู้ออกกำลังกายกลับมาอ้วนได้อีก", "แนะนำให้ผู้ที่หยุดออกกำลังกายรับประทานอาหารน้อยลง", "ให้ข้อสังเกตว่าผู้ที่หยุดออกกำลังกายจะกลับมาอ้วนอย่างรวดเร็ว"]', '2', 'ข้อสอบจริง ก.พ. ปี 2562 ชุด Paper

67. ตอบ 2) อธิบายสาเหตุที่ผู้ออกกำลังกายกลับมาอ้วนได้อีก
บทความเริ่มจากการพูดถึงคนที่ออกกำลังกายเป็นประจำว่าอ้วนเร็วกว่าคนไม่เคยออกกำลังกาย จากนั้น
