INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2562_Paper_069', '“ในประเทศจีนมีผู้ผลิตหลายรายเติมน้ำลงไปในน้ำนมดิบที่ส่งขายให้แก่โรงงานที่ผลิตอาหารต่าง ๆ เช่น นมผง อาหารทารก เป็นผลให้นมมีปริมาณโปรตีนต่ำกว่ามาตรฐาน เมื่อโรงงานที่ต้องการซื้อน้ำนมดิบเพื่อผลิตอาหารตรวจพบว่าปริมาณโปรตีนในน้ำนมดิบไม่ได้มาตรฐาน จึงปฏิเสธน้ำนมดิบที่มีการเติมน้ำเพื่อแก้ปัญหาข้างต้น ผู้ผลิตน้ำนมดิบจึงเติมเมลามีน ซึ่งเป็นสารที่มีปริมาณไนโตรเจนสูงลงไปเพิ่ม น่าวิตกว่าการกระทำดังกล่าวส่งผลให้เด็กทารกนับหมื่นนับแสนคนเจ็บป่วยด้วยโรคนิ่วในไต และทารกบางส่วนเสียชีวิตด้วยอาหารไตวาย” จากบทความข้างต้น ผู้เขียนต้องการสื่อสารความคิดเห็นตามข้อใด', '["ทารกควรบริโภคนมที่มีโปรตีนตามมาตรฐานเพื่อให้มีสุขภาพที่ดี", "ประชาชนควรร่วมมือกันต่อต้านการบริโภคนมที่ผลิตจากน้ำนมดิบมาตรฐานต่ำ", "เมนามีนที่ผู้ผลิตเพิ่มลงไปในน้ำน้ำนมดิบมีอันตรายต่อสุขภาพและชีวิตของผู้บริโภค", "ผู้ผลิตวัตถุดิบอาหาร เช่น นม ควรมีจิตสำนึกรับผิดชอบต่อสุขภาพและชีวิตของผู้บริโภค"]', '4', 'ข้อสอบจริง ก.พ. ปี 2562 ชุด Paper

68. ตอบ 4) ผู้ผลิตวัตถุดิบอาหาร เช่น นม ควรมีจิตสำนึกรับผิดชอบต่อสุขภาพและชีวิตของผู้บริโภค
จากบทความทั้งหมดจะเห็นว่ามีประโยค “น่าวิตกว่า . . .” หลังจากประโยคนี้จะสะท้อนถึงความคิดเห็น
ของผู้เขียน คือการกระทำของผู้ผลิตส่งผลต่อชีวิตของผู้บริโภค ดังนั้นผู้ผลิตควรมีจิตสำนึกในการรับผิดชอบต่อ
ส่วนรวม', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["ภาษาไทย", "บทความ"]', '2562', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2562_Paper_070', '“เพื่อน ๆ ที่มาพบกันในงานเลี้ยงรุ่น แม้วัยและสภาพร่างกายจะเปลี่ยนไปบ้าง แต่ในความรู้สึกแล้วยังเป็นเด็กไม่เปลี่ยนแปลง ทุกคนมีเส้นทางชีวิตเป็นของตนเอง สำเร็จมากบ้างน้อยบ้าง ล้มเหลวก็มีที่ยังดิ้นรนสู้กับอุปสรรคต่าง ๆ ก็ไม่น้อย แต่สิ่งที่เหมือนเดิมคือมิตรภาพระหว่างกัน แม้จะไม่ได้พบกันนานแต่พอพบหน้ากันก็ต่อติดและมีความเป็นเพื่อนที่หยิบยื่นให้กันเช่นเดิม” ข้อใดไม่ใช่ความคิดของผู้เขียนบทความข้างต้น', '["เส้นทางชีวิตของคนย่อมแตกต่างกัน", "มิตรภาพไม่อาจทำลายด้วยเวลา", "ความสำเร็จและล้มเหลวคือบทเรียน", "เวลาทำให้บางอย่างเปลี่ยนแปลง"]', '3', 'ข้อสอบจริง ก.พ. ปี 2562 ชุด Paper

69. ตอบ 3) ความสำเร็จและล้มเหลวคือบทเรียน
จากบทความสังเกตว่าแต่ละตัวเลือกถูกกล่าวถึงในแต่ละประโยค ดังนี้
1. เส้นทางชีวิตของคนย่อมแตกต่างกัน – “ทุกคนมีเส้นทางชีวิตเป็นของตนเอง”
2. มิตรภาพไม่อาจทำลายด้วยเวลา – “แต่สิ่งที่เหมือนเดิมคือมิตรภาพระหว่างกัน”
4. เวลาทำให้บางอย่างเปลี่ยนแปลง – “แม้วัยและสภาพร่างกายจะเปลี่ยนไปบ้าง”', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["ภาษาไทย", "บทความ"]', '2562', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2562_Paper_071', 'จงอ่านบทความนี้แล้วตอบคำถามข้อ 70 - 71
ดิน หิน ป่าไม้ สัตว์ป่า ล้วนอยู่ในอุ้งมือมนุษย์ที่ผลาญใช้เพื่อประโยชน์ของตรอย่างไม่คณนา จนกระทั่งวันหนึ่งเมื่อน้ำทะลักท่วมท้นมาจนเกือบมิดหลังคา ชายชรารอความช่วยเหลืออย่างอิดโรยอยู่บนยอดจั่ว ชั่วคืนเดียวเท่านั้นเองเขาก็เหลือเพียง “ชีวิต”

ข้อใดเป็นความคิดที่ผู้เขียนต้องการสื่อในบทความข้างต้น', '["ชี้ให้เห็นผลของการทำลายสิ่งแวดล้อม", "แนะให้ตระหนักถึงความไม่เที่ยงแท้ของชีวิต", "เรียกร้องให้มีผู้รับผิดชอบต่อเหตุการณ์รุนแรงในครั้งนี้", "เชิญชวนให้คนทั่วไปบริจาคเงินและสิ่งของช่วยเหลือชายชรา"]', '1', 'ข้อสอบจริง ก.พ. ปี 2562 ชุด Paper

