INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2562_Paper_083', 'Situation : Job interview
David : Good morning Miss Lee. My name is David Fort. I am the marketing Department Manager. Please have a seat.
Miss Lee : Thank you, sir ____(6)_____.
