INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2562_Paper_089', 'Mr. Kanok ________ promoted to be a general manager for two weeks.', '["has been", "have been", "had been", "is going to be"]', '1', 'ข้อสอบจริง ก.พ. ปี 2562 ชุด Paper

12. ตอบ 1) has been
Mr. Kanok ________ promoted to be a general manager for two weeks.
คำแปล : Mr. Kanok ________ เลื่อนตำแหน่งเป็นผู้จัดการทั่วไปเป็นเวลา 2 สัปดาห์
สังเกต “for two week” เป็น present perfect : S + have/has + V3
“promoted” หมายถึง ได้รับการเลื่อนตำแหน่ง เป็น Passive voice : V.to be + V3', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2562', 'Paper', 0);
