INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2563_Paper_033', 'สามเหลี่ยมมุมหนึ่งกางมากกว่ามุมที่สอง 3 เท่า มุมที่สามกางมากกว่ามุมที่สอง 20 องศา มุมที่สองมีมุมกี่องศา', '["30 องศา", "32 องศา", "52 อาศา", "96 องศา"]', '2', 'ข้อสอบจริง ก.พ. ปี 2563 ชุด Paper

33. ตอบ 2) 32 องศา
กำหนดให้มุม 1 = 3X, มุม 2 = X และ มุม 3 = X + 20
จะได้มุมภายในรูปสามเหลี่ยม 180°=3X+X+(X+20°)
180°=5X+20°
X=32°', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2563', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2563_Paper_034', 'ส้ม 199 กิโลกรัม แบ่งใส่ถุง (2/6) กิโลกรัม และขายถุงละ 15 บาท จะได้เงินเท่าไร', '["8,500", "8,785", "8,885", "8,955"]', '4', 'ข้อสอบจริง ก.พ. ปี 2563 ชุด Paper

34. ตอบ 4) 8,955 บาท
จากโจทย์ หาว่าแบ่งส้มได้กี่ถุง = 199/2 = 597 ถุง
ขายส้มถุงละ 15 บาท จะได้เงิน = 597 x 15⁶
= 8,955 บาท', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2563', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2563_Paper_035', 'เชือกหนึ่งเส้นยาว 35 ฟุต ตัดออกเป็น 2 เส้น โดยเส้นสั้นเป็น 2/5 ของเส้นยาว ถามว่าเส้นยาวยาวกี่ฟุต', '["20 ฟุต", "22 ฟุต", "24 ฟุต", "25 ฟุต"]', '4', 'ข้อสอบจริง ก.พ. ปี 2563 ชุด Paper

35. ตอบ 4) 25 ฟุต
กำหนดให้เชือกเส้นสั้นยาว = (2/5) X, เชือกเส้นสั้นยาว = X
จะได้ X+ (2/5) X = 35
5X+2X/5 = 35
7/5 X = 35
X = 25', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2563', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2563_Paper_036', 'ช่างทำถนนได้วันละ 69.50 เมตร ใช้เวลาทำถนนทั้งหมด 1 ปี6 เดือน ถนนยาวกี่กิโลเมตร', '["33 กิโลเมตร", "35 กิโลเมตร", "37 กิโลเมตร", "38 กิโลเมตร"]', '4', 'ข้อสอบจริง ก.พ. ปี 2563 ชุด Paper

36. ตอบ 4) 28 ก.ม.
จะได้ 1 ปี6 เดือน = 365 + (30x6) = 545 วัน
ทำได้วันละ 69.50 เมตร ถ้า 1 ปี6 เดือน จะทำถนนได้ 69.50 x 545 = 37,877.50 เมตร
เปลี่ยน เมตร เป็น กิโลเมตร = 37,877.50/1,000 = 37.8 กิโลเมตร', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2563', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2563_Paper_037', 'ที่เวลา 14.30 น. อยากทราบว่าเข็มสั้นและเข็มยาวทำมุมกี่องศา', '["100 องศา", "105 องศา", "115 อาศา", "120 องศา"]', '2', 'ข้อสอบจริง ก.พ. ปี 2563 ชุด Paper

37. ตอบ 2) 105 องศา
วงกลมมีมุมภายใน 360° นาฬิกา แบ่งออกเป็น 12 ช่อง จะทำมุมช่องละ 360/12 =30°
14.30 น.มีช่องห่างระหว่างเข็มสั้นและเข็มยาว 3.5 ช่อง
จะได้ 3.5 x 30° = 105°', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2563', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2563_Paper_038', 'เลขคี่สองจำนวนเรียงกัน มีผลบวกเท่ากับ 96 เลขจำนวนน้อยมีค่าเท่าใด', '["45", "47", "49", "50"]', '2', 'ข้อสอบจริง ก.พ. ปี 2563 ชุด Paper

38. ตอบ 2) 47
