INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2563_Paper_039', 'มีเงิน 1,500 บาท ซื้อปากกาได้ 10 โหล ถ้าปากกาลดราคาลงโหลละ 25 บาท จะซื้อปากกากี่ได้โหล', '["12 โหล", "13 โหล", "14 โหล", "15 โหล"]', '1', 'ข้อสอบจริง ก.พ. ปี 2563 ชุด Paper

39. ตอบ 1) 12 โหล
เงิน 1,500 บาท ซื้อปากกาได้ 10 โหล
แสดงว่า 1 โหล ราคา 1,500/10 = 150 บาท
ลดราคาลง โหลละ 25 บาท จะเหลือราคาโหลละ 150 – 25 = 125 บาท
จะสามารถซื้อได้ 1,500/125 = 12 โหล', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2563', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2563_Paper_040', 'เลข 10 จำนวน มีค่าเฉลี่ยเท่ากับ 15, เลข 15 จำนวน มีค่าเฉลี่ยเท่ากับ 10 จงหาว่าเลขทั้ง 25 จำนวนมีค่าเฉลี่ยเท่าใด', '["10", "12", "14", "15"]', '2', 'ข้อสอบจริง ก.พ. ปี 2563 ชุด Paper

40. ตอบ 2) 12
n = 10 ,x⃑ = 15 n = 15 ,y⃑ = 10
x⃑⃑⃑y⃑⃑ = (∑x + ∑y)/(10+ 15)
x⃑ = ∑x/n y⃑ = ∑y/n
= (150+150)/(10+15)
15 = ∑x/10 10 = ∑y/15
= 300/25
∑x=150 ∑y=150
=12', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2563', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2563_Paper_041', 'ซื้อสินค้ามาในราคา 3,920 ได้รับการลดครั้งแรก 20% และได้ลดเพิ่มอีก 2% ถามว่าสินค้านี้ติดป้ายราคาเท่าไร', '["4,000", "4,300", "5,000", "5,200"]', '3', 'ข้อสอบจริง ก.พ. ปี 2563 ชุด Paper

41. ตอบ 3) 5,000 บาท
กำหนดให้ ขายสินค้า 100 บาท ลด 20% จะเหลือ 80 บาท
ลดเพิ่มอีก 2% จะเหลือ 80 – ((80 × 2)/100) = 78.4 บาท
จะได้ว่า ขายสินค้า 78.4 บาท จากราคาป้าย 100 บาท
ขายสินค้าราคา 3,920 บาท จากราคาป้าย (3,920× 100)/78.4 = 5,000 บาท', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2563', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2563_Paper_042', 'สนามฟุตบอลมีความกว้างสั้นกว่าความยาว 20 เมตร โดยวัดรอบสนามได้ 360 เมตร อยากทราบว่าสนามแห่งนี้มีความกว้างกี่เมตร', '["80 เมตร", "72 เมตร", "86 เมตร", "92 เมตร"]', '1', 'ข้อสอบจริง ก.พ. ปี 2563 ชุด Paper

42. ตอบ 80 เมตร
กำหนดให้ด้านยาว = X และ ด้านกว้าง = X - 20
หาได้จากเส้นรอบรูป 360 = 2X + 2(X - 20)
360 = 2X + 2X -40
4X = 400
X = 100
จะได้ว่า สนามแห่งนี้มีความกว้าง 100 เมตร, มีความยาว 100 – 20 = 80 เมตร', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2563', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2563_Paper_043', 'ภูมีเงิน 100,000 บาท แบ่งฝากธนาคารสองแห่ง ธนาคาร A ให้ดอกเบี้ย 2% ต่อปีธนาคาร B ให้ดอกเบี้ย 1% ต่อปีสิ้นปีผลรวมดอกเบี้ยธนาคารทั้งสองแห่งเป็นเงิน 1,400 บาท จงหาผลต่างของเงินที่ภูฝากธนาคารทั้งสองแห่ง', '["20,000", "30,000", "25,000", "35,000"]', '1', 'ข้อสอบจริง ก.พ. ปี 2563 ชุด Paper

43. ตอบ 1) 20,000
กำหนดให้ ฝากธนาคาร A X บาท
ฝากธนาคาร B 100,000 - X บาท
ดอกเบี้ยธนาคาร A ; (2/100)X = 0.02X
ดอกเบี้ยธนาคาร B ; (1/100)(100,000− X) = 1,000 – 0.01X
ดอกเบี้ยธนาคารทั้งสองแห่งเป็นเงิน 1,400 บาท
จะได้ (0.02X) + (1,000 – 0.01X) = 1,400
0.01X = 400
X = 40,000
เงินฝากธนาคาร A = 40,000 บาท
เงินฝากธนาคาร B = 100,000 – 40,000 = 60,000 บาท
ดังนั้น ผลต่างของเงินที่ภูฝากธนาคารทั้งสองแห่ง 60,000 - 40,000 = 20,000 บาท', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2563', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2563_Paper_044', 'หนังสือตั้งราคากำไร 40% แล้วลดราคา 10% จากป้ายราคา จะได้กำไรเท่าไร', '["30%", "26%", "25%", "20%"]', '2', 'ข้อสอบจริง ก.พ. ปี 2563 ชุด Paper

44. ตอบ 2) 26%
กำไร 40% จากทุน 100 บาท จะได้ราคาป้าย 140 บาท
ลดราคา 10% จากป้าย 140 บาท จะได้ราคาขาย (140×90)/100 = 126 บาท
ดังนั้น ได้กำไรเท่ากับ 126 – 100 = 26%', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2563', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2563_Paper_045', 'มีขนมทั้งหมด 756 ชิ้น จัดใส่กล่องชุดเล็ก 12 ชิ้น ชุดใหญ่ 24 ชิ้น ถ้าจัดขนมได้ทั้งหมด 40 กล่อง จงหาว่าขนมชุดเล็กและชุดใหญ่มีจำนวนต่างกันกี่กล่อง', '["17 กล่อง", "9 กล่อง", "8 กล่อง", "6 กล่อง"]', '4', 'ข้อสอบจริง ก.พ. ปี 2563 ชุด Paper

45. ตอบ 4) 6 กล่อง
กำหนดให้ ชุดเล็กเป็น X กล่อง, ชุดใหญ่เป็น Y กล่อง
จำนวนชิ้นขนม ; 12X+24Y = 756 ------ (1)
จำนวนกล่อง ; X+Y = 40 ------- (2)
(2) x12 ; 12X+12Y = 480 -------- (3)
(1) – (3) ; 12Y = 276 จะได้Y = 23
แทนค่า Y = 23 ใน (2) ; X + 23 = 40
X = 17
ดังนั้น ขนมชุดเล็กและชุดใหญ่มีจำนวนต่างกัน 23 – 17 = 6 กล่อง', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2563', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2563_Paper_046', 'นาย A อายุอยู่ระหว่าง 30-50 ปีปัจจุบันอายุหาร 3 ลงตัว อีก 6 ปี อายุหาร 5 ลงตัว ถ้านับจาก 6 ปีดังกล่าวอีกกี่ปี อายุของนาย A จะครบ 60 ปี', '["10 ปี", "15 ปี", "20 ปี", "25 ปี"]', '2', 'ข้อสอบจริง ก.พ. ปี 2563 ชุด Paper

