INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2563_Paper_050', 'อีก 10 ปีสมชายอายุ 23 ปีพี่สมชายอายุ 30 ปีถ้าย้อนกลับไป 3 ปีพี่ของสมชายอายุเท่าไร', '["15 ปี", "17 ปี", "19 ปี", "20 ปี"]', '2', 'ข้อสอบจริง ก.พ. ปี 2563 ชุด Paper

