INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2563_Paper_052', 'เลขสองหลักจำนวนหนึ่งมีค่าเป็น 3 เท่าของผลรวมเลขโดดจำนวนนั้น และเมื่อรวมกับ 45 จะมีค่าเท่ากับส่วนกลับของตัวมันเอง จงหาค่าของเลขจำนวนนี้', '["23", "25", "27", "29"]', '3', 'ข้อสอบจริง ก.พ. ปี 2563 ชุด Paper

