ถ้าลดราคา 10% จะขายในราคา 140 - (140 x 10/100 ) = 126 บาท
ดังนั้น ถ้าของราคา 100 บาท ขายในราคา 126 บาท จะได้กำไร 26%', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2563', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2563_Paper_054', 'ถ้า a และ b รวมกันมีค่าเท่ากับ x และค่าเฉลี่ยของ c, d และ e มีค่าเป็นสองเท่าของ x ถ้า x มีค่ามากกว่า 3 ข้อใดถูกต้อง', '["ผลรวมของ c, d, e มีค่ามากกว่า 18", "ผลรวมของ c, d, e มีค่าเท่ากับ 18", "ผลรวมของ a, b มีค่ามากกว่าผลรวมของ c, d, e", "ผลรวมของ c, d, e มีค่าเป็น 2 เท่าของผลรวม a, b"]', '1', 'ข้อสอบจริง ก.พ. ปี 2563 ชุด Paper

54. ตอบ 1) ผลรวมของ c, d, e มีค่ามากกว่า 18
จากโจทย์ a+b = x และ Xc,d,e= 2X โดยที่X>3
1. ผลรวมของ c, d, e มีค่ามากกว่า 18 3(2X) >18 โดย X>3 -- จริง
2. ผลรวมของ c, d, e มีค่าเท่ากับ 18 3(2X) = 18 โดย X>3 -- เท็จ
3. ผลรวมของ a, b มีค่ามากกว่าผลรวมของ c, d, e X > 3(2X) โดย X>3 -- เท็จ
4. ผลรวมของ c, d, e มีค่าเป็น 2 เท่าของผลรวม a, b 3(2X) = 2X โดย X>3 -- เท็จ', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2563', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2563_Paper_055', 'จำนวนคี่ 5 จำนวนเรียงกัน มีผลรวมมากกว่าจำนวนคู่ 4 จำนวน ที่อยู่ระหว่างกลาง 29 จงหาว่าจำนวนคี่ที่มากสุดมีค่าเท่าใด', '["26", "27", "33", "35"]', '3', 'ข้อสอบจริง ก.พ. ปี 2563 ชุด Paper

55. ตอบ 3) 33
จำนวนคี่5 จำนวนเรียงกัน คือ X, X+2, X+4, X+6, X+8
จำนวนคู่4 จำนวน ที่อยู่ระหว่างจำนวนคี่คือ X+1, X+3, X+5, X+7
จะได้{X+(X+2)+(X+4)+(X+6)+(X+8)} – {(X+)+(X+3)+(X+5)+(X+7)} = 29
(5X+20)-(4X+16) = 29
X+4 = 29
X = 25
ดังนั้น จำนวนคี่ที่มากสุด คือ X+8 = 25+8 = 33', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2563', 'Paper', 0);
