INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2563_Paper_105', 'ข้อใดคือใจความสำคัญของบทความต่อไปนี้เกษตรกรรมทางเลือกเป็นการทำการเกษตรที่หลีกเลี่ยงการใช้สารเคมี เน้นการใช้ปุ๋ยอินทรีย์ผสมผสานการปลูกพืชและเลี้ยงสัตว์ งดเว้นหรือลดการใช้สารเคมีให้น้อยลง ปัจจุบันมีความต้องการพืชผักปลอดสารพิษในกลุ่มผู้รักสุขภาพ ทำให้เกษตรกรรมทางเลือกเป็นแนวทางที่เกษตรกรน่าจะอยู่รอดได้', '["สารเคมีเป็นอันตรายต่อสุขภาพของทุกคน", "เกษตรกรรมทางเลือกช่วยให้เกษตรกรอยู่รอด", "พืชผักปลอดสารพิษเป็นที่นิยมของผู้รักสุขภาพและคนทั่วไป", "เกษตรกรรมทางเลือกเป็นการทำการเกษตรที่งดเว้นหรือลดการใช้สารเคมี"]', '4', 'ข้อสอบจริง ก.พ. ปี 2563 ชุด Paper

