INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2563_Paper_106', 'ข้อใดเหมาะสมที่สุดสำหรับเป็นชื่อบทความดังต่อไปนี้กำแพงเมืองจีนสร้างขึ้นมาเพื่อป้องกันข้าศึก แต่นักประวัติศาสตร์ต่าวลงความเห็นว่ากำแพงเมืองจีนนั้นไม่สามารถป้องกันข้าศึกได้ เพราะข้าศึกสามารถโอบล้อมป้อมปราการเข้ามาได้หลายครั้ง เช่น กองทัพแมนจูสามารถยกพลข้ามกำแพงมาพิชิตแผ่นดินจีนได้ส่วนหนึ่ง นอกจากกำแพงเมืองจีนจะไม่สามารถป้องกันข้าศึกทางบกได้แล้ว เมื่อกองทัพชาติยุโรปยกทัพมาทางทะเลก็ยังสามารถกดดันให้จีนยอมจำนวนได้สำเร็จในศตวรรษที่ 19', '["ความล้มเหลวของกำแพงเมืองจีน", "มูลเหตุของการสร้างกำแพงเมืองจีน", "กองทัพแมนจูผู้พิชิตกำแพงเมืองจีน", "กองทัพเมืองจีนกับการป้องกันข้าศึกทางน้ำ"]', '1', 'ข้อสอบจริง ก.พ. ปี 2563 ชุด Paper

