INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2563_Paper_107', 'จากบทความต่อไปนี้ ข้อใดไม่ถูกต้อง การใช้กลิ่นบำบัดเป็นวิธีคลายเครียดอย่างหนึ่ง คนที่มีความเครียดเป็นประจำควรหาน้ำมันหอมระเหยติดตัวไว้เมื่อรู้สึกเหนื่อยหรือเครียดก็หยิบขึ้นมาสูดดม โดยหายใจลึก ๆ เพื่อช่วยเพิ่มออกซิเจน และกลิ่นหอมระเหยจะช่วยกระตุ้นให้เกิดความผ่อนคลาย', '["น้ำมันหอมระเหยช่วยเพิ่มออกซิเจน", "การใช้กลิ่นบำบัดเป็นวิธีคลายเครียด", "น้ำมันหอมระเหยช่วยบำบัดความเครียด", "คนที่เครียดควรพกน้ำมันหอมระเหยติดตัว"]', '1', 'ข้อสอบจริง ก.พ. ปี 2563 ชุด Paper

