INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2563_Paper_108', 'ข้อใดคือใจความสำคัญของบทความต่อไปนี้คลองแสนแสบเป็นคลองขุดใหม่ในรัชสมัยพระบาทสมเด็จพระนั่งเกล้าเจ้าอยู่หัว รัชกาลที่ 3 ใช้เวลาในการขุด 3 ปี คือระหว่างพ.ศ. 2380 – 2383 คลองแสนแสบเริ่มขุดตั้งแต่บริเวณคลองบางลำพูกับคลองโอ่งอ่างมาบรรจบกัน มาถึงวังสระปทุม ผ่านเขตหนองจอกถึงตำบลบางน้ำเปรี้ยว จังหวัดฉะเชิงเทรา แล้วเชื่อมต่อกับคลองบางขนากเพื่อออกสู่แม่น้ำบางปะกง', '["คนไทยอาศัยคลองแสนแสบทำการค้าขาย", "การขุดคลองแสนแสบทำให้การเกษตรอุดมสมบูรณ์", "คลองแสนแสบขุดเชื่อมตั้งแต่กรุงเทพฯ ถึงฉะเชิงเทรา", "ในอดีตการเดินทางต้องใช้คลองแสนแสบเป็นหลัก"]', '3', 'ข้อสอบจริง ก.พ. ปี 2563 ชุด Paper

