INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2563_Paper_109', 'ข้อใดเป็นสาระสำคัญของบทความต่อไปนี้เมื่อมีการปฏิวัติอุตสาหกรรมในตอนต้นพุทธศตวรรษที่ 24 มนุษย์รู้จักการใช้เครื่องจักรแทนแรงงานคน ทำให้การผลิตสินค้าต่าง ๆ มีหลายหลายชนิดมากขึ้นและผลิตได้ในปริมาณมากภายในระยะเวลาอันรวดเร็ว แต่การช่างที่ใช้ฝีมือและศิลปะก็ยังคงมีอยู่ต่อมา และยังได้พัฒนาทั้งในด้านรูปแบบและคุณภาพ เพื่อให้สามารถแข่งขันกับสินค้าที่ผลิตจากโรงงานอุตสาหกรรมได้', '["การปฏิวัติอุตสาหกรรมเริ่มเมื่อตอนต้นพุทธศตวรรษที่ 24 ก่อนการช่างฝีมือ", "การช่างฝีมือและเครื่องจักรอุตสาหกรรมสามารถผลิตสินค้าที่มีคุณภาพเท่าเทียมกัน", "ผลิตภัณฑ์ของช่างฝีมือมีรูปแบบสวยงามเป็นที่นิยมมากกว่าผลิตภัณฑ์จากเครื่องจักรอุตสาหกรรม", "แม้โรงงานอุตสาหกรรมจะผลิตสินค้าได้ปริมาณ แต่การช่างฝีมือก็สามารถผลิตสินค้าคุณภาพแข่งขันได้"]', '4', 'ข้อสอบจริง ก.พ. ปี 2563 ชุด Paper

