INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2563_Paper_113', 'จากข้อความต่อไปนี้ ข้อใดเป็นประโยคลำดับที่ 3', '["ความหมายของ “เผลอ” มีเพียงว่าหลงลืม ไม่ระวังตัว", "คำว่า “เผลอ” กับคำว่า “เผลอเรอ” มีความหมายใกล้เคียงกันมาก", "ถ้าพิจารณาให้ถี่ถ้วนแล้วจะเห็นได้ว่า", "ความหมายของ “เผลอเรอ” บ่งบอกถึงความหลงลืมหรือความไม่ระวังตัวอย่างมาก"]', '1', 'ข้อสอบจริง ก.พ. ปี 2563 ชุด Paper

113. ตอบ 1) ความหมายของ “เผลอ” มีเพียงว่าหลงลืม ไม่ระวังตัว
สามารถเรียบเรียงเป็นข้อความได้ตามลำดับเป็น 2 – 3 – 1 - 4 ดังนี้
คำว่า “เผลอ” กับคำว่า “เผลอเรอ” มีความหมายใกล้เคียงกันมาก ถ้าพิจารณาให้ถี่ถ้วนแล้วจะเห็นได้ว่า
ความหมายของ “เผลอ” มีเพียงว่าหลงลืม ไม่ระวังตัว ความหมายของ “เผลอเรอ” บ่งบอกถึงความหลงลืมหรือ
ความไม่ระวังตัวอย่างมาก', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["ภาษาไทย", "เรียงประโยค"]', '2563', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2563_Paper_114', 'จากข้อความต่อไปนี้ ข้อใดเป็นประโยคลำดับที่ 1', '["การศึกษาประวัติศาสตร์การดนตรีเป็นสิ่งสำคัญ", "ดนตรีเป็นวัฒนธรรมอันสูงส่งอย่างหนึ่งของชาติ", "ที่แสดงให้เห็นถึงความรุ่งเรืองและอารยธรรมของชาติเจ้าของดนตรีได้เป็นอย่างดี", "เพราะช่วยให้ได้รู้และเข้าใจในศิลปวัฒนธรรมของตนได้ดียิ่งขึ้น"]', '2', 'ข้อสอบจริง ก.พ. ปี 2563 ชุด Paper

114. ตอบ 2) ดนตรีเป็นวัฒนธรรมอันสูงส่งอย่างหนึ่งของชาติ
สามารถเรียบเรียงเป็นข้อความได้ตามลำดับเป็น 2 – 3 – 1 - 4 ดังนี้
ดนตรีเป็นวัฒนธรรมอันสูงส่งอย่างหนึ่งของชาติที่แสดงให้เห็นถึงความรุ่งเรืองและอารยธรรมของชาติ
