INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2564_Paper_024', 'แม่ค้ามีส้มโอ 350 ลูก เน่าเสีย (3/5) ลูกของทั้งหมด จะเหลือส้มโอกี่ลูกที่นำไปขายต่อได้', '["140 ลูก", "180 ลูก", "210 ลูก", "220 ลูก"]', '1', 'ข้อสอบจริง ก.พ. ปี 2564 ชุด Paper

