INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2564_Paper_025', 'แม่แบ่งเงินให้ลูก 3 คน ลูกคนที่1 ให้ 2/3 ของเงินทั้งหมด ลูกคนที่ 2 ให้ 1/3 ของเงินที่เหลือ ลูกคนที่3 ได้เงิน 3,000 บาท ต้องการทราบว่าลูกคนที่ 1 ได้เงินกี่เท่าของลูกคนที่ 2', '["2", "4", "6", "8"]', '3', 'ข้อสอบจริง ก.พ. ปี 2564 ชุด Paper

25. ตอบ 3) 6
เงินทั้งหมด x บาท
ลูกคนที่1 ได้เงิน (2/3)X บาท จะเหลือ x/3 บาท
ลูกคนที่2 ได้เงิน 1/3 × x/3 = x/9
ลูกคนที่3 ได้เงิน 2/3 × x/3 = 3,000 บาท จะได้ 2x/9 = 3,000 บาท
ดังนั้น x = 13,500 บาท
แทน x เพื่อหาจำนวนเงินที่ลูกคนที่ 1 และคนที่2 ได้รับ
ลูกคนที่1 ; (2/3)X = 2/3 × 13,500 = 9,000 บาท
ลูกคนที่2 ; x/9 = 13,500/9 = 1,500 บาท
จะได้ ลูกคนที่1/ลูกคนที่2 = 9,000/1,500 = 6 เท่า', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2564', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2564_Paper_026', 'ถังน้ำใบใหญ่ความจุ 200 ลิตร และมีถังน้ำใบเล็กทรงสี่เหลี่ยมที่มีความยาวทุกด้าน 20 เซนติเมตร หากตักน้ำโดยใช้ถังใบเล็กตักน้ำเติมกี่ครั้งถึงจะเต็มถังใบใหญ่', '["21 ครั้ง", "29 ครั้ง", "33 ครั้ง", "25 ครั้ง"]', '4', 'ข้อสอบจริง ก.พ. ปี 2564 ชุด Paper

26. ตอบ 25 ครั้ง
ถัง 1 ลิตร มี 1,000 ลูกบาศก์เซนติเมตร
ถ้าถัง 200 ลิตร จะมี (200×1,000)/1 = 200,000 ลูกบาศก์เซนติเมตร
ถังใบเล็ก มีความจุ = กว้าง × ยาว × สูง
= 20 × 20 × 20
= 8,000 ลูกบาศก์เซนติเมตร
จะได้ ความจุถังใหญ่/ความจุถังเล็ก = 200,000/8,000 = 25 ดังนั้นต้องตักทั้งหมด 25 ครั้ง', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2564', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2564_Paper_027', 'มีเงิน 5,000 บาท นำมาแลกธนบัตรใบละ 500 บาท และใบละ 100 บาท ได้มา 22 ใบ ต้องการทราบว่ามีธนบัตรใบละ 100 บาท ทั้งหมดกี่ใบ', '["15 ใบ", "11 ใบ", "19 ใบ", "23 ใบ"]', '1', 'ข้อสอบจริง ก.พ. ปี 2564 ชุด Paper

27. ตอบ 15 ใบ
ทั้งหมดแลกได้ 22 ใบ
ธนบัตร 100 บาท x ใบ และธนบัตร 500 บาท 22 - x ใบ
จะได้ว่า 100x + 500(22-x) = 5,000
100x + 11,000 – 500x = 5,000
400x = 6,000
x = 15 ใบ', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2564', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2564_Paper_028', 'กระดาษ 228 ใบ แบ่งให้เพื่อนในกลุ่ม 6 คน คนละเท่าๆกัน ต่อมาเพื่อนไม่มา 2 คน เพื่อนที่เหลือจะได้กระดาษเพิ่มคนละกี่แผ่น', '["คนละ 15 แผ่น", "คนละ 23 แผ่น", "คนละ 19 แผ่น", "คนละ 27 แผ่น"]', '3', 'ข้อสอบจริง ก.พ. ปี 2564 ชุด Paper

