INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2564_Paper_029', 'กำหนดให้ M = 1/x + 1/y และ N = x + y จงหาว่า 3M/(4N) มีค่าเท่าไร', '["3/(4xy)", "3/(4(x+y))", "4/(3xy)", "(3x)/(4y)"]', '1', 'ข้อสอบจริง ก.พ. ปี 2564 ชุด Paper

29. ตอบ 3/(4xy)
จาก M = 1/x + 1/y และ N = x + y
3M = 3 (1/x + 1/y ) และ 4N = 4 (x + y)
3M = 3 ((y+x)/(xy))
ดังนั้น 3M/(4N) = 3 ((y+x)/(xy)) ÷ 4 (x + y)
= 3 ((y+x)/(xy)) × 1/4(x+y)
= 3/(4xy)', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2564', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2564_Paper_030', 'รถคันหนึ่งขับไปยังปลายทางโดยขาไปใช้อัตราเร็ว 50 กิโลเมตรต่อชั่วโมง และขากลับใช้อัตราเร็ว 25 กิโลเมตรต่อชั่วโมงในเส้นทางเดิม รถคันนี้มีอัตรเร็วเฉลี่ยเท่าไร', '["33 1/3 กิโลเมตรต่อชั่วโมง", "37.5 กิโลเมตรต่อชั่วโมง", "50 กิโลเมตรต่อชั่วโมง", "70 กิโลเมตรต่อชั่วโมง"]', '1', 'ข้อสอบจริง ก.พ. ปี 2564 ชุด Paper

30. ตอบ 1) 33 (1/3) กิโลเมตรต่อชั่วโมง
จากสูตร อัตราเร็วเฉลี่ย = ระยะทางทั้งหมด/เวลาทั้งหมด
จะได้ อัตราเร็วเฉลี่ย = (50+50)/(1+2) = 100/3 = 33 1/3
อธิบายเพิ่มเติม
1. โจทย์กำหนดขาไป 50 กิโลเมตร ใช้เวลา 1 ชั่วโมง ดังนั้น ขากลับหากใช้ความเร็ว 25 กิโลเมตรต่อ
ชั่วโมง เดินทางทั้งหมด 50 กิโลเมตร จึงต้องใช้เวลา 2 ชั่วโมง
2. ขาไป-ขากลับ ต้องระยะทางเท่ากัน แสดงว่าระยะทาง = 50+50 กิโลเมตร และเวลา = 1+2 ชั่วโมง
จึงนำไปแทนในสูตร', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2564', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2564_Paper_031', 'ร้านค้าขายโต๊ะโดยติดป้ายราคาให้ได้กำไรตัวละ 25% ต่อมาโรงแรมซื้อโต๊ะจำนวน 20 ตัว จึงลดราคาให้8% โรงแรมจ่ายเงิน 55,200 บาท การขายครั้งนี้ร้านค้าได้กำไรจากการขายโต๊ะตัวละกี่บาท', '["340 บาท", "375 บาท", "390 บาท", "360 บาท"]', '4', 'ข้อสอบจริง ก.พ. ปี 2564 ชุด Paper

