= (2760×100×100)/(125×92)
= 2,400 บาท
ดังนั้น ได้กำไรตัวละ 2,760 – 2,400 = 360 บาท', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2564', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2564_Paper_032', 'กำหนดให้A, B เป็นจำนวนคู่และ A < B ข้อใดกล่าวถูกต้อง', '["A/B เป็นจำนวนคู่", "A – B เป็นจำนวนนับ", "B – A เป็นจำนวนคู่", "ถูกทุกข้อ"]', '3', 'ข้อสอบจริง ก.พ. ปี 2564 ชุด Paper

32. ตอบ 3) B – A เป็นจำนวนคู่
1) A/B เป็นจำนวนคู่→ เท็จ
