INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2564_Paper_041', 'ซื้อลิ้นจี่สายพันธุ์ x ราคากิโลกรัมละ 25 บาท และสายพันธุ์ y กิโลกรัมละ 32 บาท เพื่อนำมาผสมกันแล้วขายในราคากิโลกรัมละ 35 บาท ต้องผสมกันในอัตราส่วนเท่าใดจึงจะขายได้กำไร 25%', '["1 : 2", "2: 3", "4 : 3", "3 : 5"]', '3', 'ข้อสอบจริง ก.พ. ปี 2564 ชุด Paper

41. ตอบ 3) 4 : 3
ลิ้นจี่กิโลกรัมละ 25 บาท ซื้อมา x กิโลกรัม
ลิ้นจี่กิโลกรัมละ 32 บาท ซื้อมา y กิโลกรัม
ต้นทุนเท่ากับ 25x + 32y ขาย 35x + 35y หรือ 35 (x+y)
จาก % กำไร = (ราคาขาย− ราคาทุน)/ราคาทุน × 100
จะได้ 25 = (35x+35y)−(25x+32y)/(25x+32y) × 100
25/100 = 10x−3y/(25x+32y)
15x = 20y
x/y = 20/15 หรือ 4/3', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2564', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2564_Paper_042', 'ข้อมูลชุดหนึ่งมี 10 จำนวน ค่าเฉลี่ยของข้อมูลชุดนี้คือ 8.5 ต่อว่าพบว่าข้อมูลจำนวนหนึ่งอ่านผิดจาก 2.0 เป็น 0.2 ต้องการทราบว่าค่าเฉลี่ยที่ถูกต้องของข้อมูลชุดนี้คือเท่าไร', '["8.45", "8.50", "8.68", "8.89"]', '3', 'ข้อสอบจริง ก.พ. ปี 2564 ชุด Paper

42. ตอบ 3) 8.68
ครั้งแรกที่หาผิด
จาก x̄ = ผลรวมจำนวนทั้งหมด/10
จะได้ 8.5 = (x₁+x₂+x₃+...+x₉+0.2)/10
85 – 0.2 = x₁ +x₂ +x₃+...+x₉
ครั้งถัดมา (ข้อมูลถูกต้อง)
x̄
จาก = ผลรวมจำนวนทั้งหมด/10
x̄
จะได้ = (x₁+x₂+x₃+...+x₉+2.0)/10 ; แทนค่า x₁+x₂+x₃+...+x₉ เท่ากับ 85-0.2
x̄
= ((85−0.2)+2.0)/10
= 86.8/10
= 8.68', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2564', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2564_Paper_043', 'สี่เหลี่ยมจตุรัสรูปหนึ่ง หากด้านหนึ่งยาวเพิ่ม 3 ฟุต อีกด้านหนึ่งยาวลดลง 2 ฟุต ทำให้มีพื้นที่เพิ่ม 3 ตารางฟุต ต้องการทราบว่าสี่เหลี่ยมจตุรัสเดิมมีพื้นที่เท่าไร', '["49 ตารางฟุต", "64 ตารางฟุต", "81 ตารางฟุต", "100 ตารางฟุต"]', '3', 'ข้อสอบจริง ก.พ. ปี 2564 ชุด Paper

43. ตอบ 3) 81 ตารางฟุต
แทนความกว้างและความยาวของพื้นที่เดิม = x [อ้างอิงจากโจทย์บอกว่ารูปสี่เหลี่ยมจตุรัส]
ความกว้างใหม่= x - 2 และ ความยาวใหม่= x + 3
จากโจทย์ พื้นที่ใหม่ = พื้นที่เดิม + 3 ตารางฟุต
จะได้ว่า (x-2)(x+3) = พื้นที่เดิม + 3
x²– x² + x = 3 + 6
x = 9
ดังนั้น พื้นที่เดิม = 9×9 = 81 ตารางฟุต', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2564', 'Paper', 0);
