INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2564_Paper_051', 'จากเงื่อนไขต่อไปนี้จงตอบคำถามข้อ 50 - 52
