INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2564_Paper_097', 'ข้อใดกล่าวไม่ถูกต้องเกี่ยวกับบทความต่อไปนี้แมลง อุดมไปด้วยคุณค่าทางโภชนาการ มีปริมาณโปรตีนสูงใกล้เคียงกับเนื้อไก่ เนื้อปลา และเนื้อหมูแมลงส่วนใหญ่มีปริมาณโปรตีนร้อยละ 60 แมลงในกลุ่มตั๊กแตนมีปริมาณโปรตีนสูงถึงร้อยละ 77 หนอนนกมีปริมาณโปรตีนร้อยละ 76 นอกจากปริมาณโปรตีนแล้ว ความสามารถในการถูกย่อยของโปรตีนก็เป็นอีกปัจจัยหนึ่งที่แสดงถึงคุณภาพของโปรตีน จากการศึกษาพบว่า ความสามารถในการถูกย่อยของโปรตีนหนอนนกอยู่ที่ร้อยละ 54 ตั๊กแตนร้อยละ 76.3 – 90.5 ในขณะที่โปรตีนจากพืชและสัตว์มีค่าความสามารถในการถูกย่อยประมาณร้อยละ 97 และ 84 ตามลำดับ จะเห็นได้ว่าโปรตีนจากแมลงมีคุณภาพไม่แพ้โปรตีนจากพืชและสัตว์', '["ตั๊กแตนเป็นแมลงที่มีคุณภาพโปรตีนสูง", "หนอนนกมีปริมาณโปรตีนสูงกว่าแมลงส่วนใหญ่", "หนอนนกมีคุณภาพโปรตีนสูงกว่าโปรตีนจากพืชและสัตว์", "ตั๊กแตนและหนอนนกมีคุณภาพโปรตีนไม่แพ้โปรตีนจากพืชและสัตว์"]', '3', 'ข้อสอบจริง ก.พ. ปี 2564 ชุด Paper

