INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2564_Paper_098', 'จากบทความต่อไปนี้ ผู้เขียนต้องการสื่อถึงอะไร “เพื่อน” ตามพจนานุกรมมีความหมายที่กว้าง หมายถึง ผู้ชอบพอรักใครกัน ผู้สนิทสนมคุ้นเคย เช่น เพื่อนสนิท หมายถึง ผู้ร่วมสถาบันหรือร่วมอาชีพ เช่น เพื่อนร่วมงาน หมายถึง ผู้ที่มีลักษณะหรือสถานะอย่างเดียวกัน เช่น เพื่อนร่วมโลก หมายถึง ผู้ที่มีกิจกรรมร่วมกัน เช่น เพื่อนนักพัฒนา และเราก็เปรียบเทียบสิ่งมีชีวิตอื่นที่ไม่ใช่มนุษย์ให้เป็นเพื่อน เช่น ช้างเพื่อนแก้ว ขยายไปถึงสิ่งมีชีวิตที่ไม่ใช่มนุษย์และสัตว์ เช่น ต้นไม้เพื่อนยาก ปัจจุบันเทคโนโลยีสมัยใหม่ที่การเชื่อมโยงต่อกันต้องมีการ “เพิ่มเพื่อน” คราวนี้พ่อ แม่ป้า น้า อา ครูบาอาจารย์ก็ต้องเป็นเพื่อนกับลูกหลานหรือผู้อาวุโสน้อยกว่า นอกจากมนุษย์จะขอเป็นเพื่อนกันแล้ว หน่วยงานหรือธุรกิจก็ขอให้มนุษย์สมัครเป็นเพื่อนด้วย ในยุคที่อินเทอร์เน็ตเชื่อมโยงทุกอย่างเข้าหากัน เราอาจต้องกลายเป็น “เพื่อน” กับรถยนต์ โทรทัศน์ ตู้เย็น หรือบ้านของเราเอง คำจำกัดความในพจนานุกรมจึงต้องปรับปรุงต่อไปอย่างไม่สิ้นสุด', '["“เพื่อน” ตามความหมายในพจนานุกรมมีความหมายที่กว้าง", "คำจำกัดความในพจนานุกรมต้องปรับปรุงตามยุคสมัย", "เทคโลยีสมัยใหม่ทำให้ทุกสิ่งสามารถเป็นเพื่อนกันได้", "“เพื่อน” เป็นได้ทั้งสิ่งมีชีวิตและไม่มีชีวิต"]', '2', 'ข้อสอบจริง ก.พ. ปี 2564 ชุด Paper

