INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2564_Paper_099', 'จากบทความต่อไปนี้ ข้อใดสรุปได้ถูกต้อง น้ำมันงาสกัดเย็นเป็นการแปรรูปงาโดยคงคุณค่าต่าง ๆ ไม่ให้เกิดการสูญเสียเนื่องจากความร้อนระหว่างกระบวนการผลิต งานวิจัยหลายชิ้นได้ใช้เครื่องสกัดน้ำมันชนิดเกลียวอัด ตลอดจนมีการศึกษาการอัดเพื่อสกัดน้ำมันด้วยความดันต่ำกว่า 20 MPa การวิจัยนี้เป็นการศึกษาอิทธิพลของความดัน (20 – 60 MPa) และอุณหภูมิ (40 – 60 °C) ในกระบวนการผลิตต่อเปอร์เซ็นต์ความสามารถในการสกัดน้ำมันโดยวิธีเชิงกลด้วยกระบอกอัด เมื่อเปรียบเทียบกับปริมาณน้ำมันในเมล็ดงา โดยใช้ระยะเวลาในการกดอัดเท่ากับ 10 นาทีต่อตัวอย่าง พบว่ามีค่าสูงสุด สำหรับการกดอัดที่ความดัน 60 MPa และอุณหภูมิ40 °C จากนั้นได้ทำการวิเคราะห์พหุถดถอยเพื่อสร้างสมการความสัมพันธ์ระหว่างตัวแปร พบว่า ความดัน อุณหภูมิ และอิทธิพลร่วมระหว่างสองตัวแปร มีอิทธิพลต่อเปอร์เซ็นต์การสกัดน้ำมันงาอย่างมีนัยสำคัญ', '["น้ำมันงาสกัดเย็นเป็นการผลิตที่คงคุณค่าไม่ให้เกิดความสูญเสียจากความร้อน", "งานวิจัยนี้ศึกษาอิทธิพลของความดันและอุณหภูมิต่อเปอร์เซ็นต์ความสามารถในการสกัดน้ำมันโดยวิธีเชิงกลด้วยกระบอกอัด", "ความดัน 20 – 60 MPa และอุณหภูมิ 40 – 60 °C สามารถสกัดน้ำมันงาได้สูงสุด", "ความดันและอุณหภูมิมีอิทธิพลต่อเปอร์เซ็นต์การสกัดน้ำมันงา"]', '4', 'ข้อสอบจริง ก.พ. ปี 2564 ชุด Paper

99. ตอบ 4) ความดันและอุณหภูมิมีอิทธิพลต่อเปอร์เซ็นต์การสกัดน้ำมันงา
