INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2564_Paper_100', 'ข้อใดคือสาระสำคัญของบทความดังต่อไปนี้คนที่มีนิสัยชอบคาดหวังความสมบูรณ์แบบมักจะตั้งมาตรฐานสูงจนเกินจริง ทั้งยังมีความคิดแบบขาวดำในการตัดสินความสำเร็จ คือ ถ้าไม่สมบูรณ์แบบตามมาตรฐานที่ตั้งไว้ก็มองว่าเป็นความล้มเหลวโดยสิ้นเชิง หลายคนถึงกับเอาคุณค่าของตนเองไปผูกอยู่กับความสำเร็จที่สมบูรณ์แบบไร้ที่ติ กล่าวคือ ถ้าทำได้อย่างที่คาดไว้ก็จะรู้สึกว่าตนเองมีคุณค่า แต่ถ้าทำไม่ได้อย่างที่ตั้งใจก็จะรู้สึกว่าตัวเองไร้ค่า ไร้ประโยชน์ไร้ความสามารถ ซึ่งวิธีคิดแบบนี้ทำให้คนที่คาดหวังความสมบูรณ์แบบจึงไม่พอใจอะไรง่าย ๆ แม้แต่ตัวพวกเขาเอง บางคนใช้เวลากับการทำงานชิ้นหนึ่ง ๆ มากเกินความจำเป็น เพราะแม้จะทำได้สำเร็จแล้วก็ยังไม่พึงพอใจ จนงานเสร็จช้ากว่ากำหนด บางคนถึงกับไม่ยอมลงมือทำงานเพราะกลัวว่าจะทำได้ไม่ดี การมีนิสัยคาดหวังความสมบูรณ์แบบจึงกลายเป็นอุปสรรคในการทำงานมากกว่าที่จะช่วยใหเงานออกมาดี', '["คนที่มีนิสัยคาดหวังความสมบูรณ์แบบมักตั้งมาตรฐานสูงเกินจริงและอาจทำให้เกิดอุปสรรคในการทำงาน", "คนที่คาดหวังความสมบูรณ์แบบจะมีแรงผลักดันเพื่อให้ทุกอย่างเป็นไปตามมาตรฐานที่คาดหวัง", "บุคคลที่มีนิสัยชอบคาดหวังความสมบูรณ์แบบจะไม่พึงพอใจอะไรง่าย ๆ จนงานเสร็จช้ากว่ากำหนด", "ควรรู้จักปล่อยวาง ยอมรับความไม่สมบูรณ์แบบ เพราะความสำเร็จไม่จำเป็นต้องปราศจากความผิดพลาดเสมอไป"]', '1', 'ข้อสอบจริง ก.พ. ปี 2564 ชุด Paper

