INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2564_Paper_101', 'จากข้อความต่อไปนี้ ข้อใดเป็นประโยคลำดับที่ 2', '["หลังจากนั้นจึงนำสาหร่ายนั้นไปตากแห้ง", "เมื่อสาหร่ายนิ่ม จึงนำสาหร่ายไปบดให้กลายเป็นเนื้อเดียวกัน", "นำสาหร่ายแห้งมาล้างน้ำให้สะอาดเพื่อจัดการสิ่งสกปรกที่ปนมาออกให้หมด", "จากนั้นจึงนำสาหร่ายที่ตากแห้งแล้วไปต้มจนสาหร่ายนิ่ม"]', '1', 'ข้อสอบจริง ก.พ. ปี 2564 ชุด Paper

101. ตอบ 1) หลังจากนั้นจึงนำสาหร่ายนั้นไปตากแห้ง
เรียบเรียงเป็นบทความได้เป็น 3 – 1 – 4 - 2 ดังนี้
นำสาหร่ายแห้งมาล้างน้ำให้สะอาดเพื่อจัดการสิ่งสกปรกที่ปนมาออกให้หมด หลังจากนั้นจึงนำสาหร่าย
