INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2564_Paper_102', 'จากข้อความต่อไปนี้ ข้อใดเป็นประโยคลำดับที่ 2', '["ตามธรรมเนียมโบราณของประเทศอินเดียก็มีเช่นกัน", "ข้าวตอก คือ ข้าวเปลือกข้าวจ้าวที่นำมาคั่วให้เปลือกแตกออก", "สมัยอินเดียโบราณเวลารับเสด็จพระเจ้าแผ่นดินต้องโปรยข้าวตอกดอกไม้", "การบูชาด้วยข้าวตอกและดอกไม้ของไทยเป็นประเพณีมีมาแต่ดั้งเดิม"]', '4', 'ข้อสอบจริง ก.พ. ปี 2564 ชุด Paper

