INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2564_Paper_111', 'Although Nid and Noy are twins Nid is not .... Noy.', '["as strong with", "as strong as", "as stronger than", "as strong more"]', '2', 'ข้อสอบจริง ก.พ. ปี 2564 ชุด Paper

