INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2564_Paper_122', 'This IT training course will greatly .... your career.', '["please", "comfort", "benefit", "increase"]', '3', 'ข้อสอบจริง ก.พ. ปี 2564 ชุด Paper

