3. benefit มีประโยชน์ต่อ 4. increase เพิ่ม', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2564', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2564_Paper_123', 'I .... Peter last week.', '["met", "meet", "meeting", "meets"]', '1', 'ข้อสอบจริง ก.พ. ปี 2564 ชุด Paper

19. ตอบ 1) met
I . . . . Peter last week.
คำแปล : ฉัน . . . ปีเตอร์เมื่อสัปดาห์ที่แล้ว
กล่าวถึงอดีต = past simple tense : S +V2', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2564', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2564_Paper_124', 'It is too dark. The light needs to be ....', '["adjusted", "practiced", "destroyed", "suggested"]', '1', 'ข้อสอบจริง ก.พ. ปี 2564 ชุด Paper

