INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2564_Paper_125', 'Dogs often .... when greeting people or other animals.', '["bark", "to bark", "barking", "barked"]', '1', 'ข้อสอบจริง ก.พ. ปี 2564 ชุด Paper

