สังเกต structure ของประโยค จะเห็นว่าเป็น present simple โดยสังเกตจาก often adv. of frequency และ
agreement of subject and verb (ประธาน dogs นามพหูพจน์ กริยาไม่ต้องเติม s)', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2564', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2564_Paper_126', '.... is the cheapest place I can travel in summer?', '["why", "what", "where", "which"]', '3', 'ข้อสอบจริง ก.พ. ปี 2564 ชุด Paper

