1. why ทำไม 2. what อะไร 3. where ทีไหน 4. which อันไหน', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2564', 'Paper', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2564_Paper_127', 'It is .... at the mall today. There are people everywhere so I go to the market instead.', '["crowded", "moderate", "empty", "vacant"]', '1', 'ข้อสอบจริง ก.พ. ปี 2564 ชุด Paper

