INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2564_Paper_129', 'The bank robbery .... I told you about is in the local newspaper.', '["when", "which", "where", "whom"]', '2', 'ข้อสอบจริง ก.พ. ปี 2564 ชุด Paper

