INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2564_Paper_131', 'The doctor .... that I have to exercise regularly.', '["recommended", "presented", "claimed", "interviewed"]', '1', 'ข้อสอบจริง ก.พ. ปี 2564 ชุด Paper

