INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2564_Paper_134', 'Good managements is .... for running mega projects.', '["eligible", "essential", "extreme", "effortless"]', '2', 'ข้อสอบจริง ก.พ. ปี 2564 ชุด Paper

30. ตอบ 2) essential
