INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2564_Paper_161', 'หน่วยงานใดในสำนักนายกรัฐมนตรีที่มีอำนาจหน้าที่เกี่ยวกับราชการประจำทั่วไปของสำนักนายกรัฐมนตรีและราชการที่คณะรัฐมนตรีมิได้กำหนดให้เป็นหน้าที่ของกรมใดกรมหนึ่งในสังกัดสำนักนายกรัฐมนตรีโดยเฉพาะ (รอบบ่าย)', '["สำนักงานรัฐมนตรี", "สำนักเลขาธิการนายกรัฐมนตรี", "สำนักเลขาธิการคณะรรัฐมนตรี", "สำนักงานปลัดสำนักนายกรัฐมนตรี"]', '4', 'ข้อสอบจริง ก.พ. ปี 2564 ชุด Paper

