INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2564_Paper_162', 'ข้อใดมิใช่อำนาจหน้าที่ของผู้ว่าราชการจังหวัด', '["ควบคุมดูแลการบริหารราชการส่วนท้องถิ่นในอำเภอตามกฎหมาย", "บริหารราชการตามกฎหมาย ระเบียบแบบแผนของทางราชการและตามแผนพัฒนาจังหวัด", "บริหารราชการตามที่คณะรัฐมนตรี กระทรวง ทบวง กรม มอบหมายหรือตามที่นายกรัฐมนตรีสั่งการ", "เสนองบประมาณต่อกระทรวงที่เกี่ยวข้อง หรือเสนอขอจัดตั้งงบประมาณต่อสำนักงบประมาณและรายงานให้กระทรวงมหาดไทยทราบ"]', '1', 'ข้อสอบจริง ก.พ. ปี 2564 ชุด Paper

