INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2564_e-Exam_029', 'A B และ C ปัจจุบันมีอายุรวมกัน 62 ปีในอีก 5 ปีข้างหน้า B จะมีอายุ 22 ปีและ A จะมีอายุเพิ่มขึ้น 20% ของอายุปัจจุบัน จงหาว่าอีก 5 ปีข้างหน้า B และ C จะมีอายุรวมกันเท่าใด', '["40", "47", "50", "57"]', '2', 'ข้อสอบจริง ก.พ. ปี 2564 ชุด e-Exam

30. ตอบ 2) 47 ปี
ชื่อ | A | B | D
อายุปัจจุบัน | X | 17 | Y
5 ปีข้างหน้า | X+5 | 22 | Y+5
อายุปัจจุบันของA จะได้ X+5 = 120/100 X อายุปัจจุบันของ B จะได้Y = 62 –17 -25
100X+500 = 120X Y = 20
X = 25
อายุรวมกันอีก 5 ปีข้างหน้าของ B และD = 22 + (y +5)
= 22 + 20 + 5 = 47
ดังนั้น อีก 5 ปีข้างหน้า B และ C จะมีอายุรวมกัน 47 ปี', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2564', 'e-Exam', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2564_e-Exam_030', 'ถ้า X เป็นจำนวนเต็มบวกที่น้อยที่สุดหารด้วย 3 และ 9 ลงตัว Y เป็นจำนวนเต็มบวกที่น้อยที่สุดหารด้วย 2 และ 4 ลงตัว จงหาค่า X - Y โดยที่X ≠ Y', '["5", "3", "2", "1"]', '1', 'ข้อสอบจริง ก.พ. ปี 2564 ชุด e-Exam

31. ตอบ 1) 5
กำหนดให้ X เป็นจำนวนเต็มบวกที่น้อยที่สุดหารด้วย 3 และ 9 ลงตัว คือ 9
Y เป็นจำนวนเต็มบวกที่น้อยที่สุดหารด้วย 2 และ 4 ลงตัว คือ 4
ดังนั้น หาค่า X-Y = 9-4 = 5', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2564', 'e-Exam', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2564_e-Exam_031', 'นาย A B และ C ร่วมกันลงทุนในบริษัทแห่งหนึ่ง โดยหุ้นของ A และ B รวมกันเท่ากับ 36 หุ้น หุ้นของ B และ C รวมกันเท่ากับ 40 และหุ้นของ A และ C รวมกันเท่ากับ 28 หุ้น จงหาว่าคนที่ถือหุ้นน้อยที่สุด ถือหุ้นเป็นจำนวนเท่าใด', '["10", "12", "14", "16"]', '2', 'ข้อสอบจริง ก.พ. ปี 2564 ชุด e-Exam

32. ตอบ 2) 12
จากโจทย์ A + B = 36 - - - - (1)
แทน A = C–4 ใน (3) ; C – 4 + C = 28
B + C = 40 - - - - (2)
A + C = 28 - - - - (1) C = 16
B = 36 - A - - - - (4)
แทน A + C = 28 ใน (3) ; A + 16 = 28
B = 40 - C - - - - (5)
(4) = (5) ; 36 – A = 40 – C A = 12
A – C = 36 – 40
แทน A + B = 36 ใน (1) ; 12 + B = 36
A = C – 4
B = 24', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2564', 'e-Exam', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2564_e-Exam_032', 'จำนวน 6 จำนวนเรียงกัน มีผลรวมเท่ากับ 93 จงหาว่า 6 จำนวนนั้น มีจำนวนเฉพาะกี่จำนวน', '["2", "3", "4", "5"]', '1', 'ข้อสอบจริง ก.พ. ปี 2564 ชุด e-Exam

33. ตอบ 1) 2
จำนวน 6 จำนวนเรียงกัน ได้แก่X, X+1, X+2, X+3, X+4, X+5
จะได้ X+(X+1)+(X+2)+(X+3)+(X+4)+(X+5) = 93
6X + 15 = 93
X = 13
ดังนั้น จำนวน 6 จำนวนเรียงกัน คือ 13, 14, 15, 16, 17, 18', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2564', 'e-Exam', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2564_e-Exam_033', 'กำหนดให้A = 2, B = -4, C = 6 และ D = -3 จงหาค่าของ {C ÷ (A + B)} x D', '["A + B – C = -8", "A + B + C = 4", "A – C + D = -7", "A – B – D = 9"]', '4', 'ข้อสอบจริง ก.พ. ปี 2564 ชุด e-Exam

34. 4) A – B – D = 9
จากโจทย์จะได้ {C ÷ (A + B)} x D = C/(A+B) × D
