INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2564_e-Exam_037', 'กำหนดให้สี่เหลี่ยม ABCD เป็นรูปสี่เหลี่ยมจตุรัส พื้นที่แรเงาเท่ากับ 45 ตารางฟุต รูปสี่เหลี่ยม ABCD มีพื้นที่เท่าใด
<div style="margin:12px 0;display:inline-block;padding:10px 14px;border-radius:10px;background:rgba(15,23,42,0.55);border:1px solid rgba(148,163,184,0.3);"><div style="position:relative;width:136px;height:136px;border:2px solid #e2e8f0;background:rgba(148,163,184,0.42);margin:6px 18px 14px 12px;"><span style="position:absolute;left:-14px;top:-16px;font-weight:700;font-size:0.85rem;">A</span><span style="position:absolute;right:-14px;top:-16px;font-weight:700;font-size:0.85rem;">B</span><span style="position:absolute;right:-14px;bottom:-16px;font-weight:700;font-size:0.85rem;">C</span><span style="position:absolute;left:-14px;bottom:-16px;font-weight:700;font-size:0.85rem;">D</span><span style="position:absolute;right:8px;top:7px;font-size:0.78rem;font-weight:600;">3 ฟุต</span><span style="position:absolute;right:5px;bottom:8px;font-size:0.78rem;font-weight:600;">3 ฟุต</span><div style="position:absolute;left:0;bottom:0;width:96px;height:96px;background:#0f172a;border-top:2px solid #e2e8f0;border-right:2px solid #e2e8f0;display:flex;align-items:center;justify-content:center;font-size:0.76rem;color:#94a3b8;">สี่เหลี่ยมจัตุรัสใน</div></div><div style="font-size:0.8rem;color:#cbd5e1;">(แถบแรเงาด้านบนและด้านขวากว้าง 3 ฟุต พื้นที่แรเงารวม = 45 ตร.ฟุต)</div></div>', '["36", "49", "64", "81"]', '4', 'ข้อสอบจริง ก.พ. ปี 2564 ชุด e-Exam

38. ตอบ 4) 81
พื้นที่สี่เหลี่ยม MNGA = X²
พื้นที่สี่เหลี่ยม ABCD = (X+3)(X+3) = X²+6X+9
หาพื้นที่บริเวณที่แรงเงา = พท.สี่เหลี่ยม ABCD - พท.สี่เหลี่ยม MNGA
45 = (X²+6X+9) – X²
45 = 6X – 9
X = 6
ดังนั้น พื้นที่สี่เหลี่ยม ABCD = (X+3)² = (6+3)² = 81 ตารางฟุต', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2564', 'e-Exam', 0);
