INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2564_e-Exam_044', 'รูปสามเหลี่ยมรูปหนึ่ง มีมุมหนึ่งกาง 32˚ อีก 2 มุม คิดเป็นอัตราส่วน 1:3 ต้องการทราบว่ามุมที่ใหญ่ที่สุดกางกี่องศา', '["105", "111", "115", "117"]', '2', 'ข้อสอบจริง ก.พ. ปี 2564 ชุด e-Exam

