INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2564_e-Exam_045', 'ข้อสอบ 350 ข้อ ใช้เวลาทำ 3 ชั่วโมง ถ้ามีคณิตศาสตร์ 50 ข้อ และกำหนดว่าต้องใช้เวลาทำข้อละ 2 เท่าของส่วนอื่น ต้องการทราบว่าข้อสอบคณิตศาสตร์ 50 ข้อ ใช้เวลากี่นาที', '["40", "45", "50", "55"]', '2', 'ข้อสอบจริง ก.พ. ปี 2564 ชุด e-Exam

