INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2564_e-Exam_047', 'มีเหรียญ 5 สตางค์ และเหรียญ 10 สตางค์ รวมกัน 62 เหรียญ คือเป็นเงิน 4.80 บาท ต้องการทราบว่ามีเหรียญ 10 สตางค์ทั้งหมดกี่เหรียญ', '["28", "32", "34", "36"]', '3', 'ข้อสอบจริง ก.พ. ปี 2564 ชุด e-Exam

