INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2564_e-Exam_054', 'ที่ดินกว้าง 15 เมตร ยาว 30 เมตร ด้านกว้างติดกับแม่น้ำ 1 ด้าน ที่ดินโดนน้ำกัดเซาะด้านยาวหายไป 3% รังวัดที่ดินใหม่ด้านกว้างหายไป 2% ที่ดินหายไปทั้งหมดกี่เปอร์เซ็นต์', '["3", "5", "6", "7"]', '2', 'ข้อสอบจริง ก.พ. ปี 2564 ชุด e-Exam

