INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2564_e-Exam_057', 'จำนวนเต็มที่เรียงกัน 10 จำนวน มีผลบวก 5 จำนวนแรกเท่ากับ 650 ผลบวกของ 5 จำนวนหลังเท่ากับเท่าไร', '["675", "655", "690", "705"]', '1', 'ข้อสอบจริง ก.พ. ปี 2564 ชุด e-Exam

