INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2564_e-Exam_059', 'ส้มลังหนึ่งมีจำนวน 140 ผล หยิบขึ้นมาจำนวนหนึ่ง เป็นส้มดี 30 ผล เสีย 10 ผล ถ้าในลังทั้งหมดมีส้มดี 80% แสดงว่าจะเหลือส้มเสียอยู่ในลังกี่ผล', '["14 ผล", "18 ผล", "22 ผล", "26 ผล"]', '2', 'ข้อสอบจริง ก.พ. ปี 2564 ชุด e-Exam

