INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2564_e-Exam_060', 'A ซื้อรองเท้ามาราคา 900 บาท ขายให้ B ได้กำไร 25% จากนั้น B ขายต่อให้ C แต่ขาดทุน 20% ต้องการทราบว่า C ซื้อรองเท้าต่อจาก B ในราคาเท่าใด', '["900 บาท", "880 บาท", "915 บาท", "930 บาท"]', '1', 'ข้อสอบจริง ก.พ. ปี 2564 ชุด e-Exam

61. ตอบ 900 บาท
จากโจทย์ A ซื้อรองเท้ามาราคา 900 บาท ขายให้B ได้กำไร 25%
= 900 x (25/100) = 225 บาท
A ขายให้B ในราคา 900 + 225 = 1,125 บาท
จากโจทย์ B ขายต่อให้ C แต่ขาดทุน 20%
= 1,125 x (20/100) = 225 บาท
B ขายให้C ในราคา 1,125 - 225 = 900 บาท
ดังนั้น C ซื้อรองเท้าต่อจาก B ในราคา 900 บาท', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2564', 'e-Exam', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2564_e-Exam_061', 'มีเหรียญบาท เหรียญห้าบาท และเหรียญสิบบาท เป็นอัตราส่วน 3:4:5 ถ้าเหรียญทั้งหมดรวมกันได้ 2,044 บาท จงหาจำนวนเหรียญทั้งหมด', '["336 เหรียญ", "316 เหรียญ", "351 เหรียญ", "366 เหรียญ"]', '1', 'ข้อสอบจริง ก.พ. ปี 2564 ชุด e-Exam

62. ตอบ 336 เหรียญ
กำหนดให้ จำนวนเหรียญ เป็น X
จำนวนเหรียญบาท:เหรียญห้าบาท:เหรียญสิบบาท = 3:4:5
มูลค่าเหรียญบาท = 1(3X) บาท
มูลค่าเหรียญห้าบาท = 5(4X) บาท
มูลค่าเหรียญสิบบาท = 10(5X) บาท
เหรียญทั้งหมดรวมกัน → 1(3X) + 5(4X) + 10(5X) = 2,044 จะได้X = 28
จำนวนเหรียญทั้งหมด = (3X) + 5(4X) + 10(5X)
= 12X
= 12 (28) = 336', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2564', 'e-Exam', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2564_e-Exam_062', 'ตู้เย็นติดราคาไว้ 6,000 บาท ประกาศขายลดราคาลง 37% เมื่อขายได้แล้วยังคงได้กำไร 5% จงหาต้นทุนของตู้เย็น', '["3,500 บาท", "3,700 บาท", "3,600 บาท", "3,800 บาท"]', '3', 'ข้อสอบจริง ก.พ. ปี 2564 ชุด e-Exam

63. ตอบ 3,600 บาท
จากโจทย์ตู้เย็นติดราคาไว้ 6,000 บาท ลดราคา 37% → 6,000 x (37/100) = 2,220 บาท
จะขายในราคา 6,000 – 2,200 = 3,780 บาท
จากโจทย์ขายได้แล้วยังคงได้กำไร 5% → ถ้าขายของราคา 10ถ บาท ต้นทุน 105 บาท
ตู้เย็นขายราคา 3,780 บาท ต้นทุน 3,780 x (100/105) = 3,600 บาท
ดังนั้น ต้นทุนของตู้เย็นเท่ากับ 3,600 บาท', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2564', 'e-Exam', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2564_e-Exam_063', 'ปัจจุบันอัตราส่วนของอายุพี่ต่อน้องเป็น 3:2 แต่ในอีก 5 ปีข้างหน้า อัตราส่วนอายุของพี่ต่อน้องจะเป็น 4:3 แสดงว่าพี่มีอายุมากกว่าน้องกี่ปี', '["5 ปี", "3 ปี", "7 ปี", "8 ปี"]', '1', 'ข้อสอบจริง ก.พ. ปี 2564 ชุด e-Exam

64. ตอบ 5 ปี
จากโจทย์อายุพี่ต่อน้อง = 3:2 → พี่อายุ= 3X ปี, น้องอายุ= 2X ปี
อีก 5 ปีข้างหน้า → พี่อายุ= 3X+5 ปี, น้องอายุ= 2X+5 ปี
ในอีก 5 ปีข้างหน้า จะได้ (3x+5)/(2x+5) = 4/3
3(3X+5) = 4(2X+5)
9X+15 = 8X+20
X = 5
พี่มีอายุ= 3X = 3(5) = 15 ปี
น้องมีอายุ= 2X = 2(5) = 10 ปี
ดังนั้น พี่มีอายุมากกว่าน้อง 15-10 = 5 ปี', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2564', 'e-Exam', 0);
