INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2564_e-Exam_103', '“คนมอญโดยเฉพาะผู้หญิงจะเรียกงานบวชพระหรือบวชเณรว่า “ปะล็องปะยัง” หรือ “ส่งนาค(เข้าโบสถ์)” ด้วยผู้หญิงทำได้เพียงเท่านั้นไม่อาจก้าวล่วงพ้นธรณีประตูเข้าโบสถ์ร่วมพิธีอุปสมบทในอุโบสถอย่างผู้ชายได้ เข้าใกล้พิธีได้มากที่สุดเพียงหน้าประตูอุโบสถเท่านั้น ถือเป็นช่วงเวลาสุดท้ายที่ญาติฝ่ายหญิงจะได้จับเนื้อต้องตัวนาคซึ่งเป็นผู้ชายก่อนอุสมบทเป็นพระ เป็นการร่วมบุญตามประสาที่ยังมีช่องว่างในการเข้าถึงแก่นพุทธศาสนา ในอดีตวัดมอญหลายแห่งจะมีการเจาะรูขนาดเล็กไว้ที่ผนังด้านหน้าอุโบสถสำหรับให้ผู้หญิงได้จับสายสิญจน์และกรวดน้ำระหว่างทำพิธีอุปสมบท” จากบทความข้างต้น ข้อใดสรุปความได้ถูกต้อง', '["ผู้หญิงชาวมอญเชื่อว่า “ปะล็องปะยัง” ทำให้เข้าใกล้พระพุทธศาสนา", "คนมอญมีความเชื่อว่าผู้หญิงเป็นอุปสรรคต่อการบวช", "ญาติไม่สามารถเข้าไปในโบสถ์กับนาคได้", "ความเชื่ออดีตทำให้เกิดช่องว่างในการเข้าถึงพระพุทธศาสนา"]', '4', 'ข้อสอบจริง ก.พ. ปี 2564 ชุด e-Exam

