INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2564_e-Exam_104', 'ข้อความใดเป็นลำดับที่ 4', '["พืชชนิดนี้มีพื้นที่กำเนิดที่ประเทศญี่ปุ่น", "ต้นวาซาบิขยายพันธุ์ได้ยากจึงทำให้มีราคาแพง", "เขตกระจายพันธุ์ได้แก่อังกฤษ", "วาซาบิทำจากส่วนลำต้นที่อยู่ใต้ดินของต้นวาซาบิหรือแรชดิสญี่ปุ่น"]', '3', 'ข้อสอบจริง ก.พ. ปี 2564 ชุด e-Exam

