INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2564_e-Exam_105', 'It was _______ hot that I had to put my jacket off.', '["as", "very", "so", "much"]', '2', 'ข้อสอบจริง ก.พ. ปี 2564 ชุด e-Exam

1. ตอบ 2) very
It was _______ hot that I had to put my jacket off.
คำแปล : มันร้อนจนฉันต้องถอดเสื้อ
คำว่า hot มักถูกใช้ร่วมกับ very hot = ร้อนมาก(ใช้กับสภาพอากาศหรือความรู้สึกร้อน),
so hot = ร้อนแรง (ในเชิงการดึงดูด)', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2564', 'e-Exam', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2564_e-Exam_106', 'There are a large _______ of the Chinese restaurants in Yaowarat area.', '["amount", "number", "organization", "quality"]', '2', 'ข้อสอบจริง ก.พ. ปี 2564 ชุด e-Exam

2. ตอบ 2) number
There are a large _______ of the Chinese restaurants in Yaowarat area.
คำแปล : มีร้านอาหารจีน . . . . ในเยาวราช
There are แปลว่า มีต้องตามด้วยนามที่เป็นพหูพจน์ ซึ่ง number = จำนวนมาก
1. amount จำนวน/ปริมาณ (ใช้กับเอกพจน์) 2. number จำนวน
3. organization องค์กร 4. quality คุณภาพ', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2564', 'e-Exam', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2564_e-Exam_107', 'John _______ the movie many times. It could be really good.', '["watches", "has watched", "watching", "was watched"]', '2', 'ข้อสอบจริง ก.พ. ปี 2564 ชุด e-Exam

3. ตอบ 2) has watched
John _______ the movie many times. It could be really good.
คำแปล : John ดูภาพยนต์หลายครั้ง มันอาจจะดีจริงๆ
สังเกต many times ตอบเป็น present perfect ซึ่งบอกถึงเหตุการณ์ที่เกิดขึ้นในอดีตและดำเนินมาถึง
ปัจจุบัน อาจสังเกต present perfect ได้จากคำว่า since, for, several times, over and over, so far, up to
now หรือ up to the present time ในข้อนี้คือ many times แปลว่าหลายครั้ง จึงได้รูปประโยค S + have/has
+ V3', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2564', 'e-Exam', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2564_e-Exam_108', 'The lawyer has done all that is _______ by law.', '["require", "requires", "required", "requiring"]', '3', 'ข้อสอบจริง ก.พ. ปี 2564 ชุด e-Exam

4. ตอบ 3) required
The lawyer has done all that is _______ by law.
คำแปล : ทนายได้ทำทุกอย่างตามที่กฎหมายกำหนด
by law เป็น passive voice = ประธานถูกกระทำ รูปแบบคือ V.to be + V3 จึงตอบ required', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2564', 'e-Exam', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2564_e-Exam_109', 'Thai economic crisis _______ its people life.', '["affects", "affect", "affecting", "affected"]', '1', 'ข้อสอบจริง ก.พ. ปี 2564 ชุด e-Exam

