INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2564_e-Exam_113', 'You are not allowed to touch any ________ in the museum.', '["exhibit", "scene", "posture", "region"]', '1', 'ข้อสอบจริง ก.พ. ปี 2564 ชุด e-Exam

