INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2564_e-Exam_114', 'I am looking for a larger house for my family. I can’t ________ the price around here.', '["afford", "purchase", "control", "sale"]', '1', 'ข้อสอบจริง ก.พ. ปี 2564 ชุด e-Exam

