INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2564_e-Exam_115', 'Green papaya salad and grilled chicken of Thai food are good ________.', '["combination", "composition", "delicious", "delegation"]', '1', 'ข้อสอบจริง ก.พ. ปี 2564 ชุด e-Exam

