คำแปล : ส้มตำและไก่ย่างเป็นอาหารไทยที่ ________ ได้ดี
1. combination ผสมผสาน 2. composition องค์ประกอบ
3. delicious อร่อย 4. delegation มอบหมาย', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2564', 'e-Exam', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2564_e-Exam_116', 'You should be concerned ________ dehydration.', '["for", "over", "about", "by"]', '3', 'ข้อสอบจริง ก.พ. ปี 2564 ชุด e-Exam

12. ตอบ 3) about
You should be concerned ________ dehydration.
คำแปล : คุณควรจะกังวล ________ การสูญเสียน้ำ
1. for เพื่อ 2. over เกิน 3. about เกี่ยวกับ 4. by โดย', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2564', 'e-Exam', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2564_e-Exam_117', 'The hotel near the beach is the perfect ________ for conference.', '["program", "system", "venue", "model"]', '3', 'ข้อสอบจริง ก.พ. ปี 2564 ชุด e-Exam

