1. program คำสั่ง 2. system ระบบ
3. venue สถานที่พบปะ 4. model ตัวอย่าง', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["บทสนทนา"]', '2564', 'e-Exam', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2564_e-Exam_118', 'London eye is ________famous as Eiffel Tower.', '["so", "as", "the same", "similar to"]', '2', 'ข้อสอบจริง ก.พ. ปี 2564 ชุด e-Exam

14. ตอบ 2) as
