คำแปล : ฉันรู้สึกเหนื่อยกับการช้อปปิ้งออนไลน์ครั้งแรกในเมื่อวาน แต่ฉันสนุกกันมันมาก
รูปประโยคเป็นอดีต ใช้ v2 คือ enjoyed', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2564', 'e-Exam', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2564_e-Exam_121', 'I have been watching this movie ________ an hour.', '["since", "for", "as", "then"]', '2', 'ข้อสอบจริง ก.พ. ปี 2564 ชุด e-Exam

17. ตอบ 2) for
I have been watching this movie ________ an hour.
คำแปล : ฉันดูภาพยนตร์เรื่องนี้มา 1 ชั่วโมงแล้ว
1. since ตั้งแต่ 2. for 3. as ราวกับ 4. then ต่อมา
ใช้for + ระยะเวลา (บ่งบอกถึงการทำมาตั้งแต่เริ่มต้น)
ใช้since + ระยะเวลาที่เจาะจง', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2564', 'e-Exam', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2564_e-Exam_122', 'Thai families tend to have a lower birth rate ________ lifestyle choices associated with economic influence.', '["because", "due to", "to", "for"]', '1', 'ข้อสอบจริง ก.พ. ปี 2564 ชุด e-Exam

18. ตอบ 1) because
