influence. ครอบครัวไทยมีแนวโน้มของอัตราการเกิดลดลง ________ ทางเลือกของไลฟ์สไตล์ที่เกี่ยวข้องกับ
อิทธิพลทางเศรษฐกิจ
1. because เนื่องจาก 2. due to เนื่องจาก (จะต้องอยู่หลัง v. to be เสมอ)
3. to ถึง 4. for เพื่อ', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2564', 'e-Exam', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2564_e-Exam_123', 'Learning ________ of school children.', '["outlet", "Outlook", "Outcome", "Outbreak"]', '3', 'ข้อสอบจริง ก.พ. ปี 2564 ชุด e-Exam

