INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2564_e-Exam_124', 'Many human illnesses ________ by bacteria and virus.', '["caused", "Will caused", "Has caused", "Are caused"]', '3', 'ข้อสอบจริง ก.พ. ปี 2564 ชุด e-Exam

