1. speak พูด 2. read อ่าน 3. write เขียน 4. practice ฝึกฝน', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2564', 'e-Exam', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2564_e-Exam_128', 'Nearly every night he come up to say that our radio is keeping his wife _______.', '["awake", "Busy", "Happy", "Sleepy"]', '1', 'ข้อสอบจริง ก.พ. ปี 2564 ชุด e-Exam

