INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2564_e-Exam_132', 'Put the old newspaper on the bottom of the trash bag to help ________ leaks.', '["discard", "Absorb", "Spread", "Clean"]', '2', 'ข้อสอบจริง ก.พ. ปี 2564 ชุด e-Exam

