INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2564_e-Exam_133', 'There’s no paper kitchen and the landlord only _______ us use the bathroom twice.', '["tells", "Gets", "Allows", "Lets"]', '4', 'ข้อสอบจริง ก.พ. ปี 2564 ชุด e-Exam

29. ตอบ 4) lets
There’s no paper kitchen and the landlord only _______ us use the bathroom twice.
คำแปล : ที่นี่ไม่มีกระดาษซับน้ำมันและเจ้าของบ้าน _______ พวกเราใช้ห้องน้ำสองครั้งเท่านั้น
1. tells บอก 2. gets ได้รับ 3. allows อนุญาต 4. lets อนุญาต
ในที่นี้ใช้lets เนื่องจาก allow จะใช้กรณีที่ตามหลังด้วย infinitive หรือ gerund เท่านั้น', 'ภาษาอังกฤษ', 'กพ ภาค ก', 0, 'ภาษาอังกฤษ', '["Grammar"]', '2564', 'e-Exam', 0);
